"use strict";(globalThis.webpackChunkweb||=[]).push([[1374],{1374(e){e.exports=JSON.parse('{"group":"functions","count":642,"entries":{"ARMCONV":{"help":"Converts a SAS System 9 or later ARM log written in simple format to the more readable \\nlabel=item format that was used in SAS 8.2."},"ARMEND":{"help":"Indicates the termination of an application."},"ARMGTID":{"help":"Assigns a unique identifier to a transaction class."},"ARMINIT":{"help":"Starts the initialization of an application."},"ARMJOIN":{"help":"Reads the six SAS data sets created by the %ARMPROC macro, and creates SAS data sets \\nand SQL views that contain common information about applications and transactions."},"ARMPROC":{"help":"Processes an input ARM log, and outputs six SAS data sets that contain the gathered \\ninformation from the log."},"ARMSTOP":{"help":"Specifies the end of a transaction instance."},"ARMSTRT":{"help":"Specifies the start of execution of a transaction instance, and returns a unique \\nhandle that is passed to %ARMUPDT and %ARMSTOP."},"ARMUPDT":{"help":"Updates a transaction instance that has been previously started."},"ABS":{"help":"Returns the absolute value."},"ADDR":{"help":"Returns the memory address of a variable on a 32-bit platform. The value that is \\nreturned is numeric.  \\n\\nSyntax: ADDR(variable)\\n\\nRequired Argument:\\nvariable\\n  specifies a variable name.\\n\\nInteraction:\\nWhen a SAS server is in a locked-down state, the ADDR function does not execute. \\n\\n"},"ADDRLONG":{"help":"Returns the memory address of a variable on 32-bit and 64-bit platforms. \\n \\nInteraction:\\nWhen a SAS server is in a locked-down state, the ADDRLONG function does not execute. \\n\\nSyntax: ADDRLONG(variable)\\nRequired Argument:\\nvariable\\n  specifies a variable.\\n  \\nDetails:\\nThe return value is a character string that contains the binary representation of the address. \\nTo display this value, use the $HEXw. format to convert the binary value to its hexadecimal equivalent. \\nIf you store the result in a variable, that variable should be a character variable with a length of \\nat least eight characters for portability. If you assign the result to a variable that does not yet \\nhave a length defined, that variable is assigned a length of 20 characters."},"AIRY":{"help":"Returns the value of the Airy function."},"ALLPERM":{"help":"Generates all permutations of the values of several variables in a minimal change order."},"ANYALNUM":{"help":"Searches a character string for an alphanumeric character, and returns the first \\nposition at which the character is found."},"ANYALPHA":{"help":"Searches a character string for an alphabetic character, and returns the first \\nposition at which the character is found."},"ANYCNTRL":{"help":"Searches a character string for a control character, and returns the first position \\nat which that character is found."},"ANYDIGIT":{"help":"Searches a character string for a digit, and returns the first position at which \\nthe digit is found."},"ANYFIRST":{"help":"Searches a character string for a character that is valid as the first character \\nin a SAS variable name under VALIDVARNAME=V7, and returns the first position \\nat which that character is found."},"ANYGRAPH":{"help":"Searches a character string for a graphical character, and returns the first position \\nat which that character is found."},"ANYLOWER":{"help":"Searches a character string for a lowercase letter, and returns the first position at \\nwhich the letter is found."},"ANYNAME":{"help":"Searches a character string for a character that is valid in a SAS variable name \\nunder VALIDVARNAME=V7, and returns the first position at which that character \\nis found."},"ANYPRINT":{"help":"Searches a character string for a printable character, and returns the first position \\nat which that character is found."},"ANYPUNCT":{"help":"Searches a character string for a punctuation character, and returns the first position \\nat which that character is found."},"ANYSPACE":{"help":"Searches a character string for a white-space character (blank, horizontal and vertical \\ntab, carriage return, line feed, and form feed), and returns the first position at \\nwhich that character is found."},"ANYUPPER":{"help":"Searches a character string for an uppercase letter, and returns the first position \\nat which the letter is found."},"ANYXDIGIT":{"help":"Searches a character string for a hexadecimal character that represents a digit, \\nand returns the first position at which that character is found."},"ARCOS":{"help":"Returns the arccosine."},"ARCOSH":{"help":"Returns the inverse hyperbolic cosine."},"ARSIN":{"help":"Returns the arcsine."},"ARSINH":{"help":"Returns the inverse hyperbolic sine."},"ARTANH":{"help":"Returns the inverse hyperbolic tangent."},"ATAN":{"help":"Returns the arc tangent."},"ATAN2":{"help":"Returns the arc tangent of the ratio of two numeric variables."},"ATTRC":{"help":"Returns the value of a character attribute for a SAS data set."},"ATTRN":{"help":"Returns the value of a numeric attribute for a SAS data set."},"BAND":{"help":"Returns the bitwise logical AND of two arguments. If either argument contains a \\nmissing value, then the function returns a missing value and sets _ERROR_ equal \\nto 1."},"BETA":{"help":"Returns the value of the beta function."},"BETAINV":{"help":"Returns a quantile from the beta distribution with shape parameters a and b."},"BLACKCLPRC":{"help":"Calculates call prices for European options on futures, based on the Black model."},"BLACKPTPRC":{"help":"Calculates put prices for European options on futures, based on the Black model."},"BLKSHCLPRC":{"help":"Calculates call prices for European options on stocks, based on the Black-Scholes model."},"BLSHIFT":{"help":"Returns the bitwise logical left shift of two arguments. If either argument contains \\na missing value, then the function returns a missing value and sets _ERROR_ equal \\nto 1."},"BNOT":{"help":"Returns the bitwise logical NOT of an argument."},"BOR":{"help":"Returns the bitwise logical OR of two arguments. If either argument contains a \\nmissing value, then the function returns a missing value and sets _ERROR_ equal \\nto 1."},"BRSHIFT":{"help":"Returns the bitwise logical right shift of two arguments. If either argument contains \\na missing value, then the function returns a missing value and sets _ERROR_ equal to 1."},"BXOR":{"help":"Returns the bitwise logical EXCLUSIVE OR of two arguments. If either argument contains \\na missing value, then the function returns a missing value and sets _ERROR_ equal to 1."},"BYTE":{"help":"Returns one character in the ASCII or the EBCDIC collating sequence."},"ALLCOMB":{"help":"Generates all combinations of the values of n variables taken k at a time in a \\nminimal change order."},"ALLCOMBI":{"help":"Generates all combinations of the indices of n objects taken k at a time in a \\nminimal change order."},"CATS":{"help":"Removes leading and trailing blanks, and returns a concatenated character string."},"CATT":{"help":"Removes trailing blanks, and returns a concatenated character string."},"CATX":{"help":"Removes leading and trailing blanks, inserts delimiters, and returns a concatenated \\ncharacter string."},"COMPCOST":{"help":"Sets the costs of operations for later use by the COMPGED function."},"GRAYCODE":{"help":"Generates all subsets of n items in a minimal change order."},"LABEL":{"help":"Assigns a variable label to a specified character variable."},"LEXCOMB":{"help":"Generates all distinct combinations of the non-missing values of n variables taken \\nk at a time in lexicographic order."},"LEXCOMBI":{"help":"Generates all combinations of the indices of n objects taken k at a time in \\nlexicographic order."},"LEXPERK":{"help":"Generates all distinct permutations of the non-missing values of n variables \\ntaken k at a time in lexicographic order."},"LEXPERM":{"help":"Generates all distinct permutations of the non-missing values of several variables \\nin lexicographic order."},"LOGISTIC":{"help":"Returns the logistic transformation of the argument. \\n    \\nSyntax: LOGISTIC(argument)\\nRequired Argument:\\nargument\\n  is a numeric variable, constant, or expression that specifies the value of a numeric random variable. \\n  When argument is missing, the LOGISTIC function returns a missing value. \\n  \\nDetails\\nThe LOGISTIC function returns the logistic transformation of an argument. It is typically used to \\nconvert a log odds value to a value on the probability scale."},"MISSING":{"help":"Assigns missing values to the specified character or numeric variables."},"MODULE":{"help":"Calls an external routine without any return code.\\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL MODULE routine does not execute. \\n\\nSyntax: CALL MODULE(<control-string,> module-name <, argument-1, ..., argument-n>);\\n\\nRequired Argument:\\nmodule-name - is the name of the external module to use.\\n\\nOptional Arguments:\\ncontrol-string\\n  is an optional control string whose first character must be an asterisk (*), followed by any \\n  combination of the following characters:\\n    I\\n    prints the hexadecimal representations of all arguments to the CALL MODULE routine. You can use \\n    this option to help diagnose problems that are caused by incorrect arguments or attribute tables. \\n    If you specify the I option, the E option is implied.\\n    E\\n    prints detailed error messages. Without the E option (or the I option, which supersedes it), \\n    the only error message that the CALL MODULE routine generates is \\"Invalid argument to function,\\" \\n    which is usually not enough information to determine the cause of the error. The E option is \\n    useful for a production environment, whereas the I option is preferable for a development or \\n    debugging environment.\\n    H\\n    provides brief information about the syntax of the CALL MODULE routine, the attribute file format, \\n  and suggested SAS formats and informats. \\n\\nargument - is one or more arguments to pass to the requested routine."},"POKE":{"help":"Writes a value directly into memory on a 32-bit platform. \\n  \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL POKE routine does not execute. \\n\\nSyntax: CALL POKE(source, pointer <, length> <, floating-point>);\\n\\nRequired Arguments:\\nsource\\n  specifies a constant, variable, or expression that contains a value to write into memory \\npointer\\n  specifies a numeric expression that contains the virtual address of the data that the CALL POKE routine alters.\\n\\nOptional Arguments:\\nlength\\n  specifies a numeric constant, variable, or expression that contains the number of bytes to write from the source \\n  to the address that is indicated by pointer. If you omit length, the action that the CALL POKE routine takes depends \\n  on whether source is a character value or a numeric value:\\n    •If source is a character value, the CALL POKE routine copies the entire value of source to the specified memory location.\\n    •If source is a numeric value, the CALL POKE routine converts source to a long integer and writes into memory the number \\n      of bytes that constitute a pointer.\\n\\n  z/OS Specifics\\n  Under z/OS, pointers are 3 or 4 bytes long, depending on the situation. \\n\\nfloating-point\\n  specifies that the value of source is stored as a floating-point number. The value of floating-point can be any number."},"POKELONG":{"help":"Writes a value directly into memory on 32-bit and 64-bit platforms. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL POKELONG routine does not execute. \\n\\nSyntax: CALL POKELONG(source, pointer <, length> <, floating-point>);\\nRequired Arguments:\\nsource\\n  specifies a character constant, variable, or expression that contains a value to write into memory. \\npointer\\n  specifies a character string that contains the virtual address of the data that the CALL POKELONG routine alters.\\n\\nOptional Arguments:\\nlength\\n  specifies a numeric SAS expression that contains the number of bytes to write from the source to the address \\n  that is indicated by the pointer. If you omit length, the CALL POKELONG routine copies the entire value of \\n  source to the specified memory location. \\nfloating-point\\n  specifies that the value of source is stored as a floating-point number. The value of floating-point can be any number."},"PRXDEBUG":{"help":"Enables Perl regular expressions in a DATA step to send debugging output to the SAS log."},"PRXFREE":{"help":"Frees memory that was allocated for a Perl regular expression."},"PRXNEXT":{"help":"Returns the position and length of a substring that matches a pattern, and iterates \\nover multiple matches within one string."},"PRXSUBSTR":{"help":"Returns the position and length of a substring that matches a pattern."},"RANBIN":{"help":"Returns a random variate from a binomial distribution."},"RANCAU":{"help":"Returns a random variate from a Cauchy distribution."},"RANNOR":{"help":"Returns a random variate from a normal distribution."},"RANPERK":{"help":"Randomly permutes the values of the arguments, and returns a permutation of k out \\nof n values."},"RANPERM":{"help":"Randomly permutes the values of the arguments."},"RANPOI":{"help":"Returns a random variate from a Poisson distribution."},"RANTBL":{"help":"Returns a random variate from a tabled probability distribution."},"RANTRI":{"help":"Returns a random variate from a triangular distribution."},"RANUNI":{"help":"Returns a random variate from a uniform distribution."},"SET":{"help":"Links SAS data set variables to DATA step or macro variables that have the same \\nname and data type."},"SOFTMAX":{"help":"Returns the softmax value."},"SORTC":{"help":"Sorts the values of character arguments."},"SORTN":{"help":"Sorts the values of numeric arguments."},"STDIZE":{"help":"Standardizes the values of one or more variables."},"STREAMINIT":{"help":"Specifies a seed value to use for subsequent random number generation by the \\nRAND function."},"SYMPUT":{"help":"Assigns DATA step information to a macro variable."},"SYMPUTX":{"help":"Assigns a value to a macro variable, and removes both leading and trailing blanks."},"VNEXT":{"help":"Returns the name, type, and length of a variable that is used in a DATA step."},"CAT":{"help":"Does not remove leading or trailing blanks, and returns a concatenated character string."},"CATQ":{"help":"Concatenates character or numeric values by using a delimiter to separate items \\nand by adding quotation marks to strings that contain the delimiter."},"CDF":{"help":"Returns a value from a cumulative probability distribution. \\n\\nSyntax: CDF(distribution, quantile <, parameter-1, …, parameter-k>) \\n\\nRequired Arguments:\\ndistribution\\n  Is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribuion: BERNOULLI\\n      Beta distribuion: BETA\\n      Binomial distribuion: BINOMIAL\\n      Cauchy distribuion: CAUCHY\\n      Chi-Square distribuion: CHISQUARE\\n      Conway-Maxwell-Poisson distribuion: CMP\\n      Exponential distribuion: EXPONENTIAL\\n      F distribuion: F\\n      Gamma distribuion: GAMMA\\n      Generalized Poisson distribuion: GENPOISSON\\n      Geometric distribuion: GEOMETRIC\\n      Hypergeometric distribuion: HYPERGEOMETRIC\\n      Laplace distribuion: LAPLACE\\n      Logistic distribuion: LOGISTIC\\n      Lognormal distribuion: LOGNORMAL\\n      Negative binomial distribuion: NEGBINOMIAL\\n      Normal distribuion: NORMAL|GAUSS\\n      Normal mixture distribuion: NORMALMIX\\n      Pareto distribuion: PARETO\\n      Poisson distribuion: POISSON\\n      T distribuion: T\\n      Tweedie distribuion: TWEEDIE\\n      Uniform distribuion: UNIFORM\\n      Wald (inverse Gaussian) distribuion: WALD|IGAUSS\\n      Weibull distribuion: WEIBULL\\n\\n      Note: Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n\\nquantile\\n  is a numeric constant, variable, or expression that specifies the value of the random variable.\\n\\nOptional Argument: parameter-1, … , parameter-k\\n  are optional constants, variables, or expressions that specify shape, location, or scale parameters appropriate \\n  for the specific distribution."},"CEIL":{"help":"Returns the smallest integer that is greater than or equal to the argument, fuzzed \\nto avoid unexpected floating-point results."},"CEILZ":{"help":"Returns the smallest integer that is greater than or equal to the argument, using \\nzero fuzzing."},"CEXIST":{"help":"Verifies the existence of a SAS catalog or SAS catalog entry."},"CHAR":{"help":"Returns a single character from a specified position in a character string."},"CHOOSEC":{"help":"Returns a character value that represents the results of choosing from a list \\nof arguments."},"CHOOSEN":{"help":"Returns a numeric value that represents the results of choosing from a list \\nof arguments."},"CINV":{"help":"Returns a quantile from the chi-square distribution."},"CLOSE":{"help":"Closes a SAS data set."},"CMISS":{"help":"Counts the number of missing arguments."},"CNONCT":{"help":"Returns the noncentrality parameter from a chi-square distribution."},"COALESCE":{"help":"Returns the first non-missing value from a list of numeric arguments."},"COALESCEC":{"help":"Returns the first non-missing value from a list of character arguments."},"COLLATE":{"help":"Returns a character string in ASCII or EBCDIC collating sequence."},"COMB":{"help":"Computes the number of combinations of n elements taken r at a time."},"COMPARE":{"help":"Returns the position of the leftmost character by which two strings differ, or returns 0 \\nif there is no difference."},"COMPBL":{"help":"Removes multiple blanks from a character string."},"COMPGED":{"help":"Returns the generalized edit distance between two strings."},"COMPLEV":{"help":"Returns the Levenshtein edit distance between two strings."},"COMPOUND":{"help":"Returns compound interest parameters."},"COMPRESS":{"help":"Returns a character string with specified characters removed from the original string."},"CONSTANT":{"help":"Computes machine and mathematical constants."},"CONVX":{"help":"Returns the convexity for an enumerated cash flow."},"CONVXP":{"help":"Returns the convexity for a periodic cash flow stream, such as a bond."},"COS":{"help":"Returns the cosine."},"COSH":{"help":"Returns the hyperbolic cosine."},"COUNT":{"help":"Counts the number of times that a specified substring appears within a character string."},"COUNTC":{"help":"Counts the number of characters in a string that appear or do not appear in a list \\nof characters."},"COUNTW":{"help":"Counts the number of words in a character string."},"CSS":{"help":"Returns the corrected sum of squares."},"CUROBS":{"help":"Returns the observation number of the current observation."},"CV":{"help":"Returns the coefficient of variation. At least two arguments are required."},"DACCDB":{"help":"Returns the accumulated declining balance depreciation."},"DACCDBSL":{"help":"Returns the accumulated declining balance with conversion to a straight-line depreciation."},"DACCSL":{"help":"Returns the accumulated straight-line depreciation."},"DACCSYD":{"help":"Returns the accumulated sum-of-years-digits depreciation."},"DACCTAB":{"help":"Returns the accumulated depreciation from specified tables."},"DAIRY":{"help":"Returns the derivative of the AIRY function."},"DATDIF":{"help":"Returns the number of days between two dates."},"DATE":{"help":"Returns the current date as a SAS date value. \\n    \\nAlias: TODAY \\n\\nInteraction:\\nIf the value of the TIMEZONE= system option is set to a time zone name or time zone ID, the date \\nand time values that are returned for this function are determined by the time zone."},"DATEJUL":{"help":"Converts a Julian date to a SAS date value."},"DATEPART":{"help":"Extracts the date from a SAS datetime value."},"DATETIME":{"help":"Returns the current date and time of day as a SAS datetime value. \\n    \\nInteraction:\\nIf the value of the TIMEZONE= system option is set to a time zone name or time zone ID, the date \\nand time values that are returned for this function are determined by the time zone."},"DAY":{"help":"Returns the day of the month from a SAS date value."},"DCLOSE":{"help":"Closes a directory that was opened by the DOPEN function."},"DCREATE":{"help":"Returns the complete pathname of a new, external directory."},"DEPDB":{"help":"Returns the declining balance depreciation."},"DEPDBSL":{"help":"Returns the declining balance with conversion to a straight-line depreciation."},"DEPSL":{"help":"Returns the straight-line depreciation."},"DEPSYD":{"help":"Returns the sum-of-years-digits depreciation."},"DEPTAB":{"help":"Returns the depreciation from specified tables."},"DEQUOTE":{"help":"Removes matching quotation marks from a character string that begins with a quotation \\nmark, and deletes all characters to the right of the closing quotation mark."},"DEVIANCE":{"help":"Returns the deviance based on a probability distribution."},"DHMS":{"help":"Returns a SAS datetime value from date, hour, minute, and second values."},"DIF":{"help":"Returns differences between an argument and its nth lag. n specifies the number of lags."},"DIGAMMA":{"help":"Returns the value of the digamma function."},"DIM":{"help":"Returns the number of elements in an array. n specifies the dimension, in a multidimensional \\narray, for which you want to know the number of elements.\\n\\nIn CAS, this returns the dimensions of a list variable. For example:\\n\\n  x[10] = 1;\\n  y     = dim(x);\\n\\n\\ny would be set to 10"},"DINFO":{"help":"Returns information about a directory."},"DIVIDE":{"help":"Returns the result of a division that handles special missing values for ODS output."},"DNUM":{"help":"Returns the number of members in a directory."},"DOPEN":{"help":"Opens a directory, and returns a directory identifier value."},"DOPTNAME":{"help":"Returns directory attribute information."},"DOPTNUM":{"help":"Returns the number of information items that are available for a directory."},"DREAD":{"help":"Returns the name of a directory member."},"DROPNOTE":{"help":"Deletes a note marker from a SAS data set or an external file."},"DSNAME":{"help":"Returns the SAS data set name that is associated with a data set identifier."},"DUR":{"help":"Returns the modified duration for an enumerated cash flow."},"DURP":{"help":"Returns the modified duration for a periodic cash flow stream, such as a bond."},"ENVLEN":{"help":"Returns the length of an environment variable."},"ERF":{"help":"Returns the value of the (normal) error function."},"ERFC":{"help":"Returns the value of the complementary (normal) error function."},"EUCLID":{"help":"Returns the Euclidean norm of the non-missing arguments."},"EXIST":{"help":"Verifies the existence of a SAS library member."},"EXP":{"help":"Returns the value of the exponential function."},"FACT":{"help":"Computes a factorial."},"FAPPEND":{"help":"Appends the current record to the end of an external file."},"FCLOSE":{"help":"Closes an external file, directory, or directory member."},"FCOL":{"help":"Returns the current column position in the File Data Buffer (FDB)."},"FDELETE":{"help":"Deletes an external file or an empty directory."},"FETCH":{"help":"Reads the next non-deleted observation from a SAS data set into the Data Set Data Vector (DDV)."},"FETCHOBS":{"help":"Reads a specified observation from a SAS data set into the Data Set Data Vector (DDV)."},"FEXIST":{"help":"Verifies the existence of an external file that is associated with a fileref."},"FGET":{"help":"Copies data from the File Data Buffer (FDB) into a variable."},"FILEEXIST":{"help":"Verifies the existence of an external file by its physical name."},"FILENAME":{"help":"Assigns or deassigns a fileref to an external file, directory, or output device."},"FILEREF":{"help":"Verifies whether a fileref has been assigned for the current SAS session."},"FINANCE":{"help":"Computes financial calculations such as depreciation, maturation, accrued interest, net present \\nvalue, periodic savings, and internal rates of return."},"FIND":{"help":"Searches for a specific substring of characters within a character string."},"FINDC":{"help":"Searches a string for any character in a list of characters."},"FINDW":{"help":"Returns the character position of a word in a string, or returns the number of the word \\nin a string."},"FINFO":{"help":"Returns the value of a file information item."},"FINV":{"help":"Returns a quantile from the F distribution."},"FIPNAME":{"help":"Converts two-digit FIPS codes to uppercase state names."},"FIPNAMEL":{"help":"Converts two-digit FIPS codes to mixed case state names."},"FIPSTATE":{"help":"Converts two-digit FIPS codes to two-character state postal codes."},"FIRST":{"help":"Returns the first character in a character string."},"FLOOR":{"help":"Returns the largest integer that is less than or equal to the argument, fuzzed to avoid \\nunexpected floating-point results."},"FLOORZ":{"help":"Returns the largest integer that is less than or equal to the argument, using zero fuzzing."},"FNONCT":{"help":"Returns the value of the noncentrality parameter of an F distribution."},"FNOTE":{"help":"Identifies the last record that was read, and returns a value that the FPOINT function can use."},"FOPEN":{"help":"Opens an external file and returns a file identifier value."},"FOPTNAME":{"help":"Returns the name of an item of information about a file."},"FOPTNUM":{"help":"Returns the number of information items that are available for an external file."},"FPOINT":{"help":"Positions the read pointer on the next record to be read."},"FPOS":{"help":"Sets the position of the column pointer in the File Data Buffer (FDB)."},"FPUT":{"help":"Moves data to the File Data Buffer (FDB) of an external file, starting at the FDB\'s current \\ncolumn position."},"FREAD":{"help":"Reads a record from an external file into the File Data Buffer (FDB)."},"FREWIND":{"help":"Positions the file pointer to the start of the file."},"FRLEN":{"help":"Returns the size of the last record that was read, or, if the file is opened for output, \\nreturns the current record size."},"FSEP":{"help":"Sets the token delimiters for the FGET function."},"FUZZ":{"help":"Returns the nearest integer if the argument is within 1E-12 of that integer."},"FWRITE":{"help":"Writes a record to an external file."},"GAMINV":{"help":"Returns a quantile from the gamma distribution."},"GAMMA":{"help":"Returns the value of the gamma function."},"GARKHCLPRC":{"help":"Calculates call prices for European options on stocks, based on the Garman-Kohlhagen model."},"GARKHPTPRC":{"help":"Calculates put prices for European options on stocks, based on the Garman-Kohlhagen model."},"GCD":{"help":"Returns the greatest common divisor for one or more integers."},"GEODIST":{"help":"Returns the geodetic distance between two latitude and longitude coordinates."},"GEOMEAN":{"help":"Returns the geometric mean."},"GEOMEANZ":{"help":"Returns the geometric mean, using zero fuzzing."},"GETOPTION":{"help":"Returns the value of a SAS system or graphics option."},"GETVARC":{"help":"Returns the value of a SAS data set character variable."},"GETVARN":{"help":"Returns the value of a SAS data set numeric variable."},"HARMEAN":{"help":"Returns the harmonic mean."},"HARMEANZ":{"help":"Returns the harmonic mean, using zero fuzzing."},"HBOUND":{"help":"Returns the upper bound of an array. n is an optional integer constant that specifies \\nthe dimension for which you want to know the upper bound. If no n value is specified, \\nthe HBOUND function returns the upper bound of the first dimension of the array."},"HMS":{"help":"Returns a SAS time value from hour, minute, and second values."},"HOLIDAY":{"help":"Returns a SAS date value of a specified holiday for a specified year."},"HOUR":{"help":"Returns the hour from a SAS time or datetime value."},"HTMLDECODE":{"help":"Decodes a string that contains HTML numeric character references or HTML character \\nentity references, and returns the decoded string."},"HTMLENCODE":{"help":"Encodes characters using HTML character entity references, and returns the \\nencoded string."},"IBESSEL":{"help":"Returns the value of the modified Bessel function."},"IFC":{"help":"Returns a character value based on whether an expression is true, false, \\nor missing."},"IFN":{"help":"Returns a numeric value based on whether an expression is true, false, \\nor missing."},"INDEX":{"help":"Searches a character expression for a string of characters, and returns the position \\nof the string\'s first character for the first occurrence of the string."},"INDEXC":{"help":"Searches a character expression for any of the specified characters, and returns \\nthe position of that character."},"INDEXW":{"help":"Searches a character expression for a string that is specified as a word, and returns \\nthe position of the first character in the word."},"INPUT":{"help":"Returns the value that is produced when SAS converts an expression using the \\nspecified informat."},"INPUTC":{"help":"Enables you to specify a character informat at run time."},"INPUTN":{"help":"Enables you to specify a numeric informat at run time."},"INT":{"help":"Returns the integer value, fuzzed to avoid unexpected floating-point results."},"INTCINDEX":{"help":"Returns the cycle index when a date, time, or datetime interval and value \\nare specified."},"INTCK":{"help":"Returns the count of the number of interval boundaries between two dates, two \\ntimes, or two datetime values."},"INTCYCLE":{"help":"Returns the date, time, or datetime interval at the next higher seasonal cycle \\nwhen a date, time, or datetime interval is specified."},"INTFIT":{"help":"Returns a time interval that is aligned between two dates."},"INTFMT":{"help":"Returns a recommended SAS format when a date, time, or datetime interval is specified."},"INTGET":{"help":"Returns a time interval based on three date or datetime values."},"INTINDEX":{"help":"Returns the seasonal index when a date, time, or datetime interval and value are \\nspecified."},"INTNX":{"help":"Increments a date, time, or datetime value by a given time interval, and returns \\na date, time, or datetime value."},"INTRR":{"help":"Returns the internal rate of return as a fraction."},"INTSEAS":{"help":"Returns the length of the seasonal cycle when a date, time, or datetime interval \\nis specified."},"INTSHIFT":{"help":"Returns the shift interval that corresponds to the base interval."},"INTTEST":{"help":"Returns 1 if a time interval is valid, and returns 0 if a time interval is invalid."},"INTZ":{"help":"Returns the integer portion of the argument, using zero fuzzing."},"IQR":{"help":"Returns the interquartile range."},"IORCMSG":{"help":"Returns a formatted error message for _IORC_."},"IRR":{"help":"Returns the internal rate of return as a percentage."},"JBESSEL":{"help":"Returns the value of the Bessel function."},"JULDATE":{"help":"Returns the Julian date from a SAS date value."},"JULDATE7":{"help":"Returns a seven-digit Julian date from a SAS date value."},"KURTOSIS":{"help":"Returns the kurtosis."},"LAG":{"help":"Returns values from a queue. n specifies the number of lagged values."},"LARGEST":{"help":"Returns the kth largest non-missing value."},"LBOUND":{"help":"Returns the lower bound of an array. n is an optional integer constant that specifies \\nthe dimension for which you want to know the lower bound. If no n value is specified, \\nthe LBOUND function returns the lower bound of the first dimension of the array."},"LCM":{"help":"Returns the least common multiple."},"LCOMB":{"help":"Computes the logarithm of the COMB function; that is, the logarithm of the number \\nof combinations of n objects taken r at a time."},"LEFT":{"help":"Left-aligns a character string by removing leading blanks."},"QLEFT":{"help":"Left-aligns a character string by removing leading blanks."},"LENGTH":{"help":"Returns the length of a non-blank character string, excluding trailing blanks, \\nand returns 1 for a blank character string."},"LENGTHC":{"help":"Returns the length of a character string, including trailing blanks."},"LENGTHM":{"help":"Returns the amount of memory (in bytes) that is allocated for a character string."},"LENGTHN":{"help":"Returns the length of a character string, excluding trailing blanks."},"LFACT":{"help":"Computes the logarithm of the FACT (factorial) function."},"LGAMMA":{"help":"Returns the natural logarithm of the Gamma function."},"LIBNAME":{"help":"Assigns or deassigns a libref for a SAS library."},"LIBREF":{"help":"Verifies that a libref has been assigned."},"LOG":{"help":"Returns the natural (base e) logarithm."},"LOG1PX":{"help":"Returns the log of 1 plus the argument."},"LOG10":{"help":"Returns the logarithm to the base 10."},"LOG2":{"help":"Returns the logarithm to the base 2."},"LOGBETA":{"help":"Returns the logarithm of the beta function."},"LOGCDF":{"help":"Returns the logarithm of a left cumulative distribution function. \\n    \\nSyntax: LOGCDF(\'distribution\', quantile <, parameter-1, ..., parameter-k>)\\n\\nRequired Arguments:\\n\'distribution\' is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n      \\nquantile\\n  is a numeric variable, constant, or expression that specifies the value of a random variable.\\n\\nOptional Argument: \\nparameter-1, ..., parameter-k\\n  are optional shape, location, or scale parameters appropriate for the specific distribution."},"LOGPDF":{"help":"Returns the logarithm of a probability density (mass) function. \\n    \\nSyntaxLOGPDF(\'distribution\', quantile, parameter-1, ..., parameter-k)\\nRequired Arguments:\\n  \'distribution\' is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n      \\nquantile\\n  is a numeric constant, variable, or expression that specifies the value of a random variable.parameter-1, ..., parameter-k\\n  are optional shape, location, or scale parameters appropriate for the specific distribution."},"LOGSDF":{"help":"Returns the logarithm of a survival function. \\n    \\nSyntax: LOGSDF(\'distribution\', quantile, parameter-1, ..., parameter-k)\\nRequired Arguments:\\n\'distribution\' is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Note: Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n      \\nquantile\\n  is a numeric constant, variable, or expression that specifies the value of a random variable. \\n  \\nparameter-1, ..., parameter-k\\n  are optional shape, location, or scale parameters appropriate for the specific distribution."},"LOWCASE":{"help":"Converts all letters in an argument to lowercase."},"QLOWCASE":{"help":"Converts all letters in an argument to lowercase. QLOWCASE produces a result with \\nspecial characters and mnemonic operators masked."},"LPERM":{"help":"Computes the logarithm of the PERM function; that is, the logarithm of the number \\nof permutations of n objects, with the option of including r number of elements."},"LPNORM":{"help":"Returns the Lp norm of the second argument and subsequent non-missing arguments."},"MAD":{"help":"Returns the median absolute deviation from the median."},"MARGRCLPRC":{"help":"Calculates call prices for European options on stocks, based on the Margrabe model."},"MARGRPTPRC":{"help":"Calculates put prices for European options on stocks, based on the Margrabe model."},"MAX":{"help":"Returns the largest value. At least two arguments are required."},"MD5":{"help":"Returns the result of the message digest of a specified string. \\n    \\nSyntax: MD5(string)\\nRequired Argument: \\nstring\\n  specifies a character constant, variable, or expression.\\n\\nTip: Enclose a literal string of characters in quotation marks. \\n\\nExample: Generating Results with the MD5 Function\\nThis example generates results that are returned by the MD5 function.\\n  data _null_;\\n  y=md5(\'abc\');\\n  z=md5(\'access method\');\\n  put y=/ y=$hex32.;\\n  put z=/ z=$hex32.;\\n  run;\\n  \\nThe output from this program contains unprintable characters."},"MDY":{"help":"Returns a SAS date value from month, day, and year values."},"MEAN":{"help":"Returns the arithmetic mean (average). At least one non-missing argument is required. \\nOtherwise, the function returns a missing value."},"MEDIAN":{"help":"Returns the median value."},"MIN":{"help":"Returns the smalles value. At least two arguments are required."},"MINUTE":{"help":"Returns the minute from a SAS time or datetime value."},"MOD":{"help":"Returns the remainder from the division of the first argument by the second argument, \\nfuzzed to avoid most unexpected floating-point results."},"MODULEC":{"help":"Calls an external routine and returns a character value."},"MODULEN":{"help":"Calls an external routine and returns a numeric value."},"MODZ":{"help":"Returns the remainder from the division of the first argument by the second argument, \\nusing zero fuzzing."},"MONTH":{"help":"Returns the month from a SAS date value."},"MOPEN":{"help":"Opens a file by directory ID and member name, and returns either the file identifier or a 0."},"MORT":{"help":"Returns amortization parameters."},"MSPLINT":{"help":"Returns the ordinate of a monotonicity-preserving interpolating spline."},"N":{"help":"Returns the number of non-missing numeric values. At least one argument is required."},"NETPV":{"help":"Returns the net present value as a fraction."},"NLITERAL":{"help":"Converts a character string that you specify to a SAS name literal."},"NMISS":{"help":"Returns the number of missing numeric values. At least one argument is required."},"NOTALNUM":{"help":"Searches a character string for a non-alphanumeric character, and returns the first position \\nat which the character is found."},"NOTALPHA":{"help":"Searches a character string for a nonalphabetic character, and returns the first \\nposition at which the character is found."},"NOTCNTRL":{"help":"Searches a character string for a character that is not a control character, and \\nreturns the first position at which that character is found."},"NOTDIGIT":{"help":"Searches a character string for any character that is not a digit, and returns the \\nfirst position at which that character is found."},"NOTE":{"help":"Returns an observation ID for the current observation of a SAS data set."},"NOTFIRST":{"help":"Searches a character string for an invalid first character in a SAS variable name under \\nVALIDVARNAME=V7, and returns the first position at which that character is found."},"NOTGRAPH":{"help":"Searches a character string for a non-graphical character, and returns the first position \\nat which that character is found."},"NOTLOWER":{"help":"Searches a character string for a character that is not a lowercase letter, and returns \\nthe first position at which that character is found."},"NOTNAME":{"help":"Searches a character string for an invalid character in a SAS variable name under \\nVALIDVARNAME=V7, and returns the first position at which that character is found."},"NOTPRINT":{"help":"Searches a character string for a nonprintable character, and returns the first \\nposition at which that character is found."},"NOTPUNCT":{"help":"Searches a character string for a character that is not a punctuation character, \\nand returns the first position at which that character is found."},"NOTSPACE":{"help":"Searches a character string for a character that is not a white-space character \\n(blank, horizontal and vertical tab, carriage return, line feed, and form feed), \\nand returns the first position at \\nwhich that character is found."},"NOTUPPER":{"help":"Searches a character string for a character that is not an uppercase letter, and \\nreturns the first position at which that character is found."},"NOTXDIGIT":{"help":"Searches a character string for a character that is not a hexadecimal character, \\nand returns the first position at which that character is found."},"NPV":{"help":"Returns the net present value with the rate expressed as a percentage."},"NVALID":{"help":"Checks the validity of a character string for use as a SAS variable name."},"NWKDOM":{"help":"Returns the date for the nth occurrence of a weekday for the specified month and year."},"OPEN":{"help":"Opens a SAS data set."},"ORDINAL":{"help":"Returns the kth smallest of the missing and nonmissing values. At least two arguments \\nare required."},"PATHNAME":{"help":"Returns the physical name of an external file or a SAS library, or returns a blank."},"PCTL":{"help":"Returns the percentile that corresponds to the percentage. n is a digit from 1 to 5 \\nwhich specifies the definition of the percentile to be computed."},"PDF":{"help":"Returns a value from a probability density (mass) distribution. \\n\\nSyntax: PDF(distribution, quantile <, parameter-1, ... , parameter-k>)\\nRequired Arguments:\\ndistribution\\n  Is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Note: Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n      \\nquantile\\n  is a numeric constant, variable, or expression that specifies the value of the random variable.\\n\\nOptional Argument: \\nparameter-1, ..., parameter-k\\n  are optional numeric constants, variables, or expressions that specify the values of shape, location, or \\n  scale parameters that are appropriate for the specific distribution."},"PMF":{"help":"Alias for the PDF function."},"PEEK":{"help":"Stores the contents of a memory address in a numeric variable on a 32-bit platform. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the PEEK function does not execute. \\n\\nSyntax: PEEK(address <, length>)\\nRequired Argument: \\naddress\\n  is a numeric constant, variable, or expression that specifies the memory address.\\n\\nOptional Argument:\\nlength\\n  is a numeric constant, variable, or expression that specifies the data length.\\n  \\n  Default: a 4-byte address pointer\\n  Range: 2–8"},"PEEKC":{"help":"Stores the contents of a memory address in a character variable on a 32-bit platform. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the PEEKC function does not execute. \\n\\nSyntax: PEEKC(address <, length>)\\n\\nRequired Argument:\\naddress\\n  is a numeric constant, variable, or expression that specifies the memory address.\\n\\nOptional Argument: \\nlength\\n  is a numeric constant, variable, or expression that specifies the data length.\\n\\n  Default: 8, unless the variable length has already been set (for example, by the LENGTH statement)\\n  Range: 1–32,767"},"PEEKCLONG":{"help":"Stores the contents of a memory address in a character variable on 32-bit and 64-bit platforms. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the PEEKCLONG function does not execute. \\n\\nSyntax: PEEKCLONG(address <, length>)\\nRequired Argument: \\naddress\\n  specifies a character constant, variable, or expression that contains the binary pointer address.\\n\\nOptional Argument:\\nlength\\n  is a numeric constant, variable, or expression that specifies the length of the character data.\\n\\nDefault: 8\\nRange: 1–32,767\\nDetails:\\nIf you do not have access to the memory storage location that you are requesting, the PEEKCLONG \\nfunction returns an Invalid argument error."},"PEEKLONG":{"help":"Stores the contents of a memory address in a numeric variable on 32-bit and 64-bit platforms. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the PEEKLONG function does not execute. \\n\\nSyntax: PEEKLONG(address <, length>) \\n\\nRequired Argument:\\naddress\\n  specifies a character constant, variable, or expression that contains the binary pointer address.\\n\\nOptional Argument:\\nlength\\n  is a numeric constant, variable, or expression that specifies the length of the character data.\\n\\n  Default: 4 on 32-bit computers; 8 on 64-bit computers\\n  Range: 1–4 on 32-bit computers; 1–8 on 64-bit computers\\n\\nDetails:\\nIf you do not have access to the memory storage location that you are requesting, the PEEKLONG function \\nreturns an Invalid argument error."},"PERM":{"help":"Computes the number of permutations of n items that are taken r at a time."},"POINT":{"help":"Locates an observation that is identified by the NOTE function."},"POISSON":{"help":"Returns the probability from a Poisson distribution."},"PROBBETA":{"help":"Returns the probability from a beta distribution."},"PROBBNML":{"help":"Returns the probability from a binomial distribution."},"PROBBNRM":{"help":"Returns a probability from a bivariate normal distribution."},"PROBCHI":{"help":"Returns the probability from a chi-square distribution."},"PROBF":{"help":"Returns the probability from an F distribution."},"PROBGAM":{"help":"Returns the probability from a gamma distribution."},"PROBHYPR":{"help":"Returns the probability from a hypergeometric distribution."},"PROBIT":{"help":"Returns a quantile from the standard normal distribution."},"PROBMC":{"help":"Returns a probability or a quantile from various distributions for multiple \\ncomparisons of means."},"PROBNEGB":{"help":"Returns the probability from a negative binomial distribution."},"PROBNORM":{"help":"Returns the probability from the standard normal distribution."},"PROBT":{"help":"Returns the probability from a t distribution."},"PROPCASE":{"help":"Converts all words in an argument to proper case."},"PRXCHANGE":{"help":"Performs a pattern-matching replacement."},"PRXMATCH":{"help":"Searches for a pattern match and returns the position at which the pattern is found."},"PRXPAREN":{"help":"Returns the last bracket match for which there is a match in a pattern."},"PRXPARSE":{"help":"Compiles a Perl regular expression (PRX) that can be used for pattern matching of \\na character value."},"PRXPOSN":{"help":"Returns a character string that contains the value for a capture buffer."},"PTRLONGADD":{"help":"Returns the pointer address as a character variable on 32-bit and 64-bit platforms."},"PUT":{"help":"Returns a value using a specified format."},"PUTC":{"help":"Enables you to specify a character format at run time. \\n    \\nSyntax: PUTC(value, format-specification <, w>)\\n\\nRequired Arguments:\\nvalue\\n  specifies a character value to be formatted.format-specification\\n  is a character format that you want to apply to value.\\n  Here are valid format forms:\\n    •format-name\\n    •format-name.\\n    •format-namew. \\n    \\n    Except for format-name, you can use –L, –R, and –C in format-specification to left-align, \\n    right-align, and center your output. For example, you can use \'upcase.-c’ as the value for \\n    the second argument, format-specification.\\n\\nOptional Argument:\\nw\\n  is a numeric constant, variable, or expression that specifies a width to apply to the format.\\n\\n  Interaction:\\n  If you specify a width here, it overrides any width specification in the format."},"PUTN":{"help":"Enables you to specify a numeric format at run time. \\n    \\nSyntax: PUTN(value, format-specification <, w <, d>>)\\n\\nRequired Arguments: \\nvalue\\n  specifies a numeric value to be formatted.  \\nformat-specification\\n  is the numeric format that you want to apply to value.\\n  Here are valid format forms:\\n    •format-name\\n    •format-name.\\n    •format-namew.\\n    •format-namew.d\\n  Except for format-name, you can use –L, –R, and –C in format-specification to left-align, \\n  right-align, and center your output. For example, you can use \'weekdate.-c’ as the value \\n  for the second argument, format-specification.\\n\\nOptional Arguments:\\nw\\n  is a numeric constant, variable, or expression that specifies a width to apply to the format.\\n\\n  Interaction:\\n  If you specify a width here, it overrides any width specification in the format.\\n\\nd\\n  is a numeric constant, variable, or expression that specifies the number of decimal places to use.\\n  \\n  Interaction:\\n  If you specify a number here, it overrides any decimal-place specification in the format."},"PVP":{"help":"Returns the present value for a periodic cash flow stream (such as a bond), with repayment of \\nprincipal at maturity."},"QTR":{"help":"Returns the quarter of the year from a SAS date value."},"QUANTILE":{"help":"Returns the quantile from a distribution that you specify. \\n    \\nSyntax: QUANTILE(distribution, probability, parameter-1, …, parameter-k)\\nRequired Arguments: \\ndistribution is a character constant, variable, or expression that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Note: Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n\\nprobability\\n  is a numeric constant, variable, or expression that specifies the value of a random variable. \\nparameter-1, …, parameter-k\\n  are optional shape, location, or scale parameters appropriate for the specific distribution."},"QUOTE":{"help":"Adds double quotation marks to a character value."},"RAND":{"help":"Generates random numbers from a distribution that you specify."},"RANEXP":{"help":"Returns a random variate from an exponential distribution."},"RANGAM":{"help":"Returns a random variate from a gamma distribution."},"RANGE":{"help":"Returns the range of the nonmissing values. At least one nonmissing argument is required."},"RANK":{"help":"Returns the position of a character in the ASCII or EBCDIC collating sequence."},"RENAME":{"help":"Renames a member of a SAS library, an entry in a SAS catalog, an external file, or a directory."},"REPEAT":{"help":"Returns a character value that consists of the first argument repeated n+1 times."},"RESOLVE":{"help":"Returns the resolved value of the argument after it has been processed by the macro facility."},"REVERSE":{"help":"Reverses a character string."},"REWIND":{"help":"Positions the data set pointer at the beginning of a SAS data set."},"RIGHT":{"help":"Right aligns a character expression."},"RMS":{"help":"Returns the root mean square of the nonmissing arguments."},"ROUND":{"help":"Rounds the first argument to the nearest multiple of the second argument, or to the nearest \\ninteger when the second argument is omitted."},"ROUNDE":{"help":"Rounds the first argument to the nearest multiple of the second argument, and returns an \\neven multiple when the first argument is halfway between the two nearest multiples."},"ROUNDZ":{"help":"Rounds the first argument to the nearest multiple of the second argument, using \\nzero fuzzing."},"SAVING":{"help":"Returns the future value of a periodic saving."},"SCAN":{"help":"Returns the nth word from a character string."},"SCANQ":{"help":"Returns the nth word from a character expression, ignoring delimiters that are \\nenclosed in quotation marks."},"SDF":{"help":"Returns a survival function. \\n    \\nSyntax: SDF(distribution, quantile, parameter-1, ..., parameter-k)\\nRequired Arguments: \\ndistribution\\n  Is a character string that identifies the distribution. Valid distributions are as follows:\\n\\n      Bernoulli distribution: \'BERNOULLI\'\\n      Beta distribution: \'BETA\'\\n      Binomial distribution: \'BINOMIAL\'\\n      Cauchy distribution: \'CAUCHY\'\\n      Chi-Square distribution: \'CHISQUARE\'\\n      Conway-Maxwell-Poisson distribution: \'CMP\'\\n      Exponential distribution: \'EXPONENTIAL\'\\n      F distribution: \'F\'\\n      Gamma distribution: \'GAMMA\'\\n      Generalized Poisson distribution: \'GENPOISSON\'\\n      Geometric distribution: \'GEOMETRIC\'\\n      Hypergeometric distribution: \'HYPERGEOMETRIC\'\\n      Laplace distribution: \'LAPLACE\'\\n      Logistic distribution: \'LOGISTIC\'\\n      Lognormal\'LOGNORMAL\'\\n      Negative binomial distribution: \'NEGBINOMIAL\'\\n      Normal distribution: \'NORMAL\'|\'GAUSS\'\\n      Normal mixture distribution: \'NORMALMIX\'\\n      Pareto distribution: \'PARETO\'\\n      Poisson distribution: \'POISSON\'\\n      T distribution: \'T\'\\n      Tweedie distribution: \'TWEEDIE\').\\n      Uniform distribution: \'UNIFORM\'\\n      Wald (inverse Gaussian) distribution: \'WALD\'|\'IGAUSS\'\\n      Weibull distribution: \'WEIBULL\'\\n\\n      Note: Except for T, F, and NORMALMIX, you can minimally identify any distribution by its first four characters. \\n      \\nquantile\\n  is a numeric constant, variable, or expression that specifies the value of a random variable. \\n  \\nparameter-1, ..., parameter-k\\n  are optional shape, location, or scale parameters appropriate for the specific distribution."},"SECOND":{"help":"Returns the second from a SAS time or datetime value."},"SIGN":{"help":"Returns the sign of a value."},"SIN":{"help":"Returns the sine."},"SINH":{"help":"Returns the hyperbolic sine."},"SKEWNESS":{"help":"Returns the skewness of the nonmissing arguments. At least 3 arguments are required."},"SLEEP":{"help":"For a specified number of seconds (or fraction thereof), this function suspends the execution of a program that invokes \\nit. From the syntax SLEEP(n, unit), n is the number of seconds to suspend (as a constant, variable or \\nexpression), unless the unit of time is modified by the second argument. The second parameter, unit, \\nis a numeric constant, variable, or expression that specifies the unit of time, as a power of 10, which \\nis applied to n. For example, unit=1 corresponds to a second, unit=0.001 to a millisecond, unit=0.000001 \\nto a microsecond, and so on. Range: n ≥ 0."},"SMALLEST":{"help":"Returns the kth smallest nonmissing value."},"SOUNDEX":{"help":"Encodes a string to facilitate searching."},"SPEDIS":{"help":"Determines the likelihood of two words matching, expressed as the asymmetric spelling \\ndistance between the two words."},"SQRT":{"help":"Returns the square root of a value."},"STD":{"help":"Returns the standard deviation of the nonmissing arguments. At least two nonmissing \\narguments are required."},"STDERR":{"help":"Returns the standard error of the mean of the nonmissing arguments. At least two \\nnonmissing arguments are required."},"STFIPS":{"help":"Converts state postal codes to FIPS state codes."},"STNAME":{"help":"Converts state postal codes to uppercase state names."},"STNAMEL":{"help":"Converts state postal codes to mixed case state names."},"STRIP":{"help":"Returns a character string with all leading and trailing blanks removed."},"SUBPAD":{"help":"Returns a substring that has a length you specify, using blank padding if necessary."},"SUBSTR":{"help":"Extracts a substring from an argument."},"QSUBSTR":{"help":"%QSUBSTR produces a substring of a character string, masking special characters and \\nmnemonic operators."},"SUBSTRN":{"help":"Returns a substring, allowing a result with a length of zero."},"SUM":{"help":"Returns the sum of the nonmissing arguments."},"SUMABS":{"help":"Returns the sum of the absolute values of the non-missing arguments."},"SYMEXIST":{"help":"Returns an indication of the existence of a macro variable."},"SYMGET":{"help":"Returns the value of a macro variable during DATA step execution."},"SYMGLOBL":{"help":"Returns an indication of whether a macro variable is in global scope to the DATA \\nstep during DATA step execution."},"SYMLOCAL":{"help":"Returns an indication of whether a macro variable is in local scope to the DATA \\nstep during DATA step execution."},"SYSMSG":{"help":"Returns error or warning message text from processing the last data set or external \\nfile function."},"SYSPARM":{"help":"Returns the system parameter string."},"SYSPROCESSID":{"help":"Returns the process ID of the current process."},"SYSPROCESSNAME":{"help":"Returns the process name that is associated with a given process ID, or returns \\nthe name of the current process."},"SYSPROD":{"help":"Determines whether a product is licensed."},"SYSRC":{"help":"Returns a system error number."},"SYSTEM":{"help":"Issues an operating environment command during a SAS session, and returns the \\nsystem return code."},"TAN":{"help":"Returns the tangent."},"TANH":{"help":"Returns the hyperbolic tangent."},"TIME":{"help":"Returns the current time of day as a numeric SAS time value. \\n    \\nInteraction:\\nIf the value of the TIMEZONE= system option is set to a time zone name or time zone ID, the date \\nand time values that are returned for this function are determined by the time zone."},"TIMEPART":{"help":"Extracts a time value from a SAS datetime value."},"TINV":{"help":"Returns a quantile from the t distribution."},"TNONCT":{"help":"Returns the value of the noncentrality parameter from the Student\'s t distribution."},"TODAY":{"help":"Returns the current date as a numeric SAS date value. \\n    \\nAlias: DATE \\n\\nInteraction:\\nIf the value of the TIMEZONE= system option is set to a time zone name or time zone ID, the date \\nand time values that are returned for this function are determined by the time zone."},"TRANSLATE":{"help":"Replaces specific characters in a character string."},"TRANSTRN":{"help":"Replaces all occurrences of a substring found in a character string, allowing a \\nzero-length replacement string."},"TRANWRD":{"help":"Replaces or removes all occurrences of a substring in a character string."},"TRIGAMMA":{"help":"Returns the value of the trigamma function."},"TRIM":{"help":"Removes trailing blanks from a character string, and returns one blank if the string \\nis missing."},"QTRIM":{"help":"Removes trailing blanks from a character string, and returns one blank if the string \\nis missing. QTRIM produces a result with special characters and mnemonic operators \\nmasked."},"TRIMN":{"help":"Removes trailing blanks from character expressions, and returns a string with a length \\nof zero if the expression is missing."},"TRUNC":{"help":"Truncates a numeric value to a specified number of bytes."},"UNIFORM":{"help":"Returns a random variate from a uniform distribution."},"UPCASE":{"help":"Converts all letters in an argument to uppercase."},"QUPCASE":{"help":"Converts all letters in an argument to uppercase. %QUPCASE masks special characters \\nand mnemonic operators in its result."},"URLDECODE":{"help":"Returns a string that was decoded using the URL escape syntax."},"URLENCODE":{"help":"Returns a string that was encoded using the URL escape syntax."},"USS":{"help":"Returns the uncorrected sum of squares of the nonmissing arguments. At least one \\nnonmissing argument is required."},"UUIDGEN":{"help":"Returns the short or binary form of a Universal Unique Identifier (UUID)."},"VAR":{"help":"Returns the variance of the nonmissing arguments. At least two nonmissing arguments \\nare required."},"VARFMT":{"help":"Returns the format that is assigned to a SAS data set variable."},"VARINFMT":{"help":"Returns the informat that is assigned to a SAS data set variable."},"VARLABEL":{"help":"Returns the label that is assigned to a SAS data set variable."},"VARLEN":{"help":"Returns the length of a SAS data set variable."},"VARNAME":{"help":"Returns the name of a SAS data set variable."},"VARNUM":{"help":"Returns the number of a variable\'s position in a SAS data set."},"VARRAY":{"help":"Returns a value that indicates whether the specified name is an array."},"VARRAYX":{"help":"Returns a value that indicates whether the value of the specified argument is an array."},"VARTYPE":{"help":"Returns the data type of a SAS data set variable."},"VERIFY":{"help":"Returns the position of the first character in a string that is not in any of several \\nother strings."},"VFORMAT":{"help":"Returns the format that is associated with the specified variable."},"VFORMATD":{"help":"Returns the decimal value of the format that is associated with the specified variable."},"VFORMATDX":{"help":"Returns the decimal value of the format that is associated with the value of the \\nspecified argument."},"VFORMATN":{"help":"Returns the format name that is associated with the specified variable."},"VFORMATNX":{"help":"Returns the format name that is associated with the value of the specified argument."},"VFORMATW":{"help":"Returns the format width that is associated with the specified variable."},"VFORMATWX":{"help":"Returns the format width that is associated with the value of the specified argument."},"VFORMATX":{"help":"Returns the format that is associated with the value of the specified argument."},"VINARRAY":{"help":"Returns a value that indicates whether the specified variable is a member of an array."},"VINARRAYX":{"help":"Returns a value that indicates whether the value of the specified argument is a member \\nof an array."},"VINFORMAT":{"help":"Returns the informat that is associated with the specified variable."},"VINFORMATD":{"help":"Returns the decimal value of the informat that is associated with the specified variable."},"VINFORMATDX":{"help":"Returns the decimal value of the informat that is associated with the value of the \\nspecified variable."},"VINFORMATN":{"help":"Returns the informat name that is associated with the specified variable."},"VINFORMATNX":{"help":"Returns the informat name that is associated with the value of the specified argument."},"VINFORMATW":{"help":"Returns the informat width that is associated with the specified variable."},"VINFORMATWX":{"help":"Returns the informat width that is associated with the value of the specified argument."},"VINFORMATX":{"help":"Returns the informat that is associated with the value of the specified argument."},"VLABEL":{"help":"Returns the label that is associated with the specified variable."},"VLABELX":{"help":"Returns the label that is associated with the value of the specified argument."},"VLENGTH":{"help":"Returns the compile-time (allocated) size of the specified variable."},"VLENGTHX":{"help":"Returns the compile-time (allocated) size for the variable that has a name that is the \\nsame as the value of the argument."},"VNAME":{"help":"Returns the name of the specified variable."},"VNAMEX":{"help":"Validates the value of the specified argument as a variable name."},"VTYPE":{"help":"Returns the type (character or numeric) of the specified variable."},"VTYPEX":{"help":"Returns the type (character or numeric) for the value of the specified argument."},"VVALUE":{"help":"Returns the formatted value that is associated with the variable that you specify."},"VVALUEX":{"help":"Returns the formatted value that is associated with the argument that you specify."},"WEEK":{"help":"Returns the week-number value."},"WEEKDAY":{"help":"From a SAS date value, returns an integer that corresponds to the day of the week."},"WHICHC":{"help":"Searches for a character value that is equal to the first argument, and returns the index \\nof the first matching value."},"WHICHN":{"help":"Searches for a numeric value that is equal to the first argument, and returns the index \\nof the first matching value."},"YEAR":{"help":"Returns the year from a SAS date value."},"YIELDP":{"help":"Returns the yield-to-maturity for a periodic cash flow stream, such as a bond."},"YRDIF":{"help":"Returns the difference in years between two dates."},"YYQ":{"help":"Returns a SAS date value from year and quarter year values."},"ZIPCITY":{"help":"Returns a city name and the two-character postal code that corresponds to a zip code."},"ZIPCITYDISTANCE":{"help":"Returns the geodetic distance between two zip code locations."},"ZIPFIPS":{"help":"Converts zip codes to two-digit FIPS codes."},"ZIPNAME":{"help":"Converts zip codes to uppercase state names."},"ZIPNAMEL":{"help":"Converts zip codes to mixed case state names."},"ZIPSTATE":{"help":"Converts zip codes to two-character state postal codes."},"ASCEBC":{"help":"Converts an input character string from ASCII to EBCDIC."},"EBCASC":{"help":"Converts an input character string from EBCDIC to ASCII."},"FILEATTR":{"help":"Returns the attribute information for a specified file."},"FINDFILE":{"help":"Searches a directory for a file."},"GETDVI":{"help":"Returns a specified item of information from a device."},"GETJPI":{"help":"Retrieves job-process information."},"GETLOG":{"help":"Returns information about a DCL logical name."},"GETMSG":{"help":"Translates an OpenVMS error code into text."},"GETQUOTA":{"help":"Retrieves disk quota information."},"GETSYM":{"help":"Returns the value of a DCL symbol."},"GETTERM":{"help":"Returns the characteristics of your terminal device."},"NODENAME":{"help":"Returns the name of the current node."},"PUTLOG":{"help":"Creates an OpenVMS logical-name in your process-level logical name table."},"PUTSYM":{"help":"Creates a DCL symbol in the parent SAS process."},"SETTERM":{"help":"Modifies a characteristic of your terminal device."},"TERMIN":{"help":"Allows simple input from SYS$INPUT."},"TERMOUT":{"help":"Allows simple output to SYS$OUTPUT."},"TTCLOSE":{"help":"Closes a channel that was previously assigned by TTOPEN."},"TTCONTRL":{"help":"Modifies the characteristics of a channel that was previously assigned by TTOPEN."},"TTOPEN":{"help":"Assigns an I/O channel to a terminal."},"TTREAD":{"help":"Reads characters from the channel assigned by TTOPEN."},"TTWRITE":{"help":"Writes characters to the channel assigned by TTOPEN."},"VMS":{"help":"Spawns a subprocess and executes a DCL command."},"BQUOTE":{"help":"Mask special characters and mnemonic operators in a resolved value at macro execution."},"NRBQUOTE":{"help":"Mask special characters and mnemonic operators in a resolved value at macro execution."},"EVAL":{"help":"Evaluates arithmetic and logical expressions using integer arithmetic."},"NRQUOTE":{"help":"Masks special characters, including & and %, and mnemonic operators in a resolved value \\nat macro execution."},"STR":{"help":"Masks special characters, excluding & and %, and mnemonic operators in constant text \\nduring macro compilation."},"NRSTR":{"help":"Masks special characters, including & and %, and mnemonic operators in constant text \\nduring macro compilation."},"QSCAN":{"help":"Searches for a word and masks special characters and mnemonic operators."},"SUPERQ":{"help":"Masks all special characters and mnemonic operators at macro execution but prevents \\nfurther resolution of the value."},"SYSEVALF":{"help":"Evaluates arithmetic and logical expressions using floating-point arithmetic."},"SYSFUNC":{"help":"Execute SAS functions or user-written functions."},"QSYSFUNC":{"help":"Execute SAS functions or user-written functions. %QSYSFUNC masks special characters \\nand mnemonic operators such as & % \' \\" ( ) + - * / < > = ¬ ^ ~ ; , #  blank AND OR \\nNOT EQ NE LE LT GE GT IN."},"SYSGET":{"help":"Returns the value of the specified operating environment variable."},"UNQUOTE":{"help":"During macro execution, unmasks all special characters and mnemonic operators \\nfor a value."},"CMPRES":{"help":"Compress multiple blanks and remove leading and trailing blanks."},"QCMPRES":{"help":"Compress multiple blanks and remove leading and trailing blanks.  QCMPRES produces \\na result with special characters and mnemonic operators masked."},"COMPSTOR":{"help":"Compiles macros and stores them in a catalog in a permanent SAS library."},"DATATYP":{"help":"Returns the data type of a value."},"DQCASE":{"help":"Returns a character value with standardized capitalization."},"DQGENDER":{"help":"Returns a gender determination from the name of an individual."},"DQGENDERINFOGET":{"help":"Returns the name of the parse definition that is associated with the specified \\ngender definition."},"DQGENDERPARSED":{"help":"Returns a gender determination from the parsed name of an individual."},"DQIDENTIFY":{"help":"Returns a category name from a character value."},"DQLOCALEGUESS":{"help":"Returns the name of the locale that is most likely represented by a character value."},"DQLOCALEINFOGET":{"help":"Returns information about locales."},"DQLOCALEINFOLIST":{"help":"Displays the names of the definitions in a locale and returns a count of those definitions."},"DQMATCH":{"help":"Returns a match code from a character value."},"DQMATCHINFOGET":{"help":"Returns the name of the parse definition that is associated with a match definition."},"DQMATCHPARSED":{"help":"Returns a match code from a parsed character value."},"DQPARSE":{"help":"Returns a parsed character value."},"DQPARSEINFOGET":{"help":"Returns the token names in a parse definition."},"DQPARSETOKENGET":{"help":"Returns a token from a parsed character value."},"DQPARSETOKENPUT":{"help":"Inserts a token into a parsed character value and returns the updated parsed \\ncharacter value."},"DQPATTERN":{"help":"Returns a pattern analysis from an input character value."},"DQSCHEMEAPPLY":{"help":"Applies a scheme and returns a transformed value."},"DQSRVARCHJOB":{"help":"Runs an dfPower Architect job on a DataFlux Integration Server and returns a job \\nidentifier."},"DQSRVCOPYLOG":{"help":"Copies a job\'s log file from a DataFlux Integration Server."},"DQSRVDELETELOG":{"help":"Deletes a job\'s log file from a DataFlux Integration Server."},"DQSRVJOBSTATUS":{"help":"Returns the status of a job that was submitted to a DataFlux Integration Server."},"DQSRVKILLJOB":{"help":"Terminates a job that is running on a DataFlux Integration Server."},"DQSRVPROFJOBFILE":{"help":"Runs a file-type Profile job on a DataFlux Integration Server and returns a job \\nidentifier."},"DQSRVPROFJOBREP":{"help":"Runs a repository-type Profile job on a DataFlux Integration Server and returns \\na job identifier."},"DQSRVUSER":{"help":"Authenticates a user on a DataFlux Integration Server."},"DQSTANDARDIZE":{"help":"Returns a character value after standardizing casing, spacing, and format, and \\napplies a common representation to certain words and abbreviations."},"DQTOKEN":{"help":"Returns a token from a character value."},"EFFRATE":{"help":"Returns the effective annual interest rate.\\n    \\nSyntax:\\nEFFRATE(compounding-interval, rate) \\n\\nRequired Arguments:\\ncompounding-interval \\n  is a SAS interval. This value represents how often rate compounds. \\n\\nrate \\n  is numeric. rate is a nominal annual interest rate (expressed as a percentage) that \\n  is compounded at each compounding interval."},"MVALID":{"help":"Checks the validity of a character string for use as a SAS member name.\\n    \\nSyntax:\\nMVALID(libname, string, memtype<,validmemname>) \\n\\nRequired Arguments:\\nlibname \\n  specifies a character constant, variable, or expression that associates a SAS library \\n  with a libref. Leading and trailing blanks are ignored. \\nstring \\n  specifies a character constant, variable, or expression that is checked to determine \\n  whether its value can be used as a SAS member name. Leading and trailing blanks are ignored. \\nmemtype \\n  specifies a character constant, variable, or expression that is the member type of the \\n  member name that you are using. Leading and trailing blanks are ignored. The value of \\n  memtype is not validated. The following member types are available: \\n\\n    ACCESS specifies access descriptor files that are created by SAS/ACCESS.  \\n    CATALOG specifies SAS catalogs. \\n    DATA specifies SAS data files. \\n    FDB specifies a financial database. \\n    ITEMSTOR specifies a SAS data set that consists of pieces of information that can be \\n      accessed independently. The SAS Registry is an example of an item store.  \\n    MDDB specifies a multidimensional database. \\n    PROGRAM specifies stored compiled SAS programs. \\n    VIEW specifies SAS views. \\n\\nOptional Argument:\\nvalidmemname \\n  specifies a character constant, variable, or expression. The values for validmemname can \\n  be uppercase or lowercase. Leading and trailing blanks are ignored. The following list \\n  contains the values that you can use with validmemname: \\n    COMPAT | COMPATIBLE\\n    EXTEND      \\n    Default: VALIDMEMNAME= is set to COMPAT."},"NOMRATE":{"help":"Returns the nominal annual interest rate.\\n    \\nSyntax:\\nNOMRATE(compounding-interval, rate) \\n\\nRequired Arguments:\\ncompounding-interval \\n  is a SAS interval. This value represents how often the returned value is compounded. \\nrate \\n  is numeric. rate is the effective annual interest rate (expressed as a percentage) \\n  that is compounded at each interval."},"SAVINGS":{"help":"Returns the balance of a periodic savings by using variable interest rates.\\n    \\nSyntax:\\nSAVINGS(base-date, initial-deposit-date, deposit-amount, deposit-number, \\ndeposit-interval, compounding-interval, date-1, rate-2 <,date-2, rate-2,...>) \\n\\nRequired Arguments: \\nbase-date \\n  is a SAS date. The value that is returned is the balance of the savings at base-date. \\ninitial-deposit-date \\n  is a SAS date. initial-deposit-date is the date of the first deposit. Subsequent deposits \\n  are at the beginning of subsequent deposit intervals. \\ndeposit-amount \\n  is numeric. All deposits are assumed constant. deposit-amount is the value of each deposit. \\ndeposit-number \\n  is a positive integer. deposit-number is the number of deposits. \\ndeposit-interval \\n  is a SAS interval. deposit-interval is the frequency at which deposits are made. \\ncompounding-interval \\n  is a SAS interval. compounding-interval is the compounding interval. \\ndate \\n  is a SAS date. Each date is paired with a rate. date is the time that rate takes effect. \\nrate \\n  is a numeric percentage. Each rate is paired with a date. rate is the interest rate that \\n  starts on date."},"SOAPWEB":{"help":"Calls a Web service by using basic Web authentication; credentials are provided in the arguments.\\n    \\nSyntax:\\nSOAPWEB (IN, URL <,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains the SOAP request. \\nURL \\n  specifies a character value that is the URL of the Web service endpoint. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWEBUSERNAME \\n  specifies a character value that is a user name for either basic or NTLM Web authentication. \\nWEBPASSWORD \\n  specifies a character value that is a password for either basic or NTLM Web authentication. \\n  Encodings that are produced by PROC PWENCODE are supported. \\nWEBDOMAIN \\n  specifies a character value that is the domain or realm for the user name and password for NTLM authentication. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nPROXYPORT \\n  specifies a numeric value that is an HTTP proxy server port. \\nPROXYHOST \\n  specifies a character value that is an HTTP proxy server host. \\nPROXYUSERNAME \\n  specifies a character value that is an HTTP proxy server user name. \\nPROXYPASSWORD \\n  specifies a character value that is an HTTP proxy server password. Encodings that are produced by PROC PWENCODE are supported. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging logging output."},"SOAPWEBMETA":{"help":"Calls a Web service by using basic Web authentication; credentials for the authentication \\ndomain are retrieved from metadata. \\n\\nSyntax:\\nSOAPWEBMETA (IN, URL <,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains the SOAP request. \\nURL \\n  specifies a character value that is the URL of the Web service endpoint. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWEBAUTHDOMAIN \\n  specifies a character value that is the authentication domain from which to retrieve a user \\n  name and password from metadata for basic Web authentication. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nPROXYPORT \\n  specifies a numeric value that is an HTTP proxy server port. \\nPROXYHOST \\n  specifies a character value that is an HTTP proxy server host. \\nPROXYUSERNAME \\n  specifies a character value that is an HTTP proxy server user name. \\nPROXYPASSWORD \\n  specifies a character value that is an HTTP proxy server password. Encodings that are produced \\n  by PROC PWENCODE are supported. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging logging output."},"SOAPWIPSERVICE":{"help":"Calls a SAS registered Web service by using WS-Security authentication; credentials \\nare provided in the arguments.\\n\\nSyntax:\\nSOAPWIPSERVICE (IN, SERVICE <,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains the SOAP request. \\nSERVICE \\n  specifies the service name of the endpoint service as the service is stored in the Service Registry. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWSSUSERNAME \\n  specifies a character value that is a WS-Security user name. \\nWSSPASSWORD \\n  specifies a character value that is a WS-Security password, which is the password for WSSUSERNAME. \\n  Encodings that are produced by PROC PWENCODE are supported. \\nENVFILE \\n  specifies a character value that is the location of the SAS environments file. \\nENVIRONMENT \\n  specifies a character value that is the environment defined in the SAS environments file to use. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging logging output."},"SOAPWIPSRS":{"help":"Calls a SAS registered Web service by using WS-Security authentication; credentials \\nare provided in the arguments.\\n\\nSyntax:\\nSOAPWIPSRS (IN, URL, SRSURL<,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains \\n  the SOAP request. \\nURL \\n  specifies a character value that is the URL of the Web service endpoint. \\nSRSURL \\n  specifies a character value that is the URL of the System Registry Service. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWSSUSERNAME \\n  specifies a character value that is a WS-Security user name. \\nWSSPASSWORD \\n  specifies a character value that is a WS-Security password, which is the password for WSSUSERNAME. \\n  Encodings that are produced by PROC PWENCODE are supported. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set \\n  time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging \\n  logging output."},"SOAPWS":{"help":"Calls a Web service by using WS-Security authentication; credentials are provided \\nin the arguments. \\n\\nSyntax:\\nSOAPWS (IN, URL<,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains the SOAP request. \\nURL \\n  specifies a character value that is the URL of the Web service endpoint. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWSSUSERNAME \\n  specifies a character value that is a WS-Security user name. \\nWSSPASSWORD \\n  specifies a character value that is a WS-Security password, which is the password for WSSUSERNAME. \\n  Encodings that are produced by PROC PWENCODE are supported. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nPROXYPORT \\n  specifies a numeric value that is an HTTP proxy server port. \\nPROXYHOST \\n  specifies a character value that is an HTTP proxy server host. \\nPROXYUSERNAME \\n  specifies a character value that is an HTTP proxy server user name. \\nPROXYPASSWORD \\n  specifies a character value that is an HTTP proxy server password. Encodings that are produced \\n  by PROC PWENCODE are supported. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging logging output."},"SOAPWSMETA":{"help":"Calls a Web service by using WS-Security authentication; credentials for the provided \\nauthentication domain are retrieved from metadata.\\n\\nSyntax: \\nSOAPWSMETA (IN, URL <,options>) \\n\\nRequired Arguments:\\nIN \\n  specifies a character value that is the fileref. IN is used to input XML data that contains the SOAP request. \\nURL \\n  specifies a character value that is the URL of the Web service endpoint. \\n\\nOptional Arguments:\\nOUT \\n  specifies a character value that is the fileref where the SOAP response output XML will be written. \\nSOAPACTION \\n  specifies a character value that is a SOAPAction element to invoke on the Web service. \\nWSSAUTHDOMAIN \\n  specifies a character value that is the authentication domain for which to retrieve credentials \\n  to be used for WS-Security authentication. \\nMUSTUNDERSTAND \\n  specifies a numeric value that is the setting for the mustUnderstand attribute in the SOAP header. \\nPROXYPORT \\n  specifies a numeric value that is an HTTP proxy server port. \\nPROXYHOST \\n  specifies a character value that is an HTTP proxy server host. \\nPROXYUSERNAME \\n  specifies a character value that is an HTTP proxy server user name. \\nPROXYPASSWORD \\n  specifies a character value that is an HTTP proxy server password. Encodings that are produced \\n  by PROC PWENCODE are supported. \\nCONFIGFILE \\n  specifies a character value that is a Spring configuration file that is used primarily to set time-out values. \\nDEBUG \\n  specifies a character value that is the full path to a file that is used for debugging logging output."},"SQUANTILE":{"help":"Returns the quantile from a distribution when you specify the right probability (SDF). \\n\\nSyntax:\\n  SQUANTILE(dist, probability, parm-1, ... , parm-k) \\n\\nRequired Arguments \\ndist \\n  is a character constant, variable, or expression that identifies the distribution. \\n  Valid distributions are as follows: \\n      Bernoulli  BERNOULLI \\n      Beta  BETA \\n      Binomial  BINOMIAL \\n      Cauchy  CAUCHY \\n      Chi-Square  CHISQUARE \\n      Exponential  EXPONENTIAL \\n      F  F \\n      Gamma  GAMMA \\n      Generalized Poisson  GENPOISSON \\n      Geometric  GEOMETRIC \\n      Hypergeometric  HYPERGEOMETRIC \\n      Laplace  LAPLACE \\n      Logistic  LOGISTIC \\n      Lognormal  LOGNORMAL \\n      Negative binomial  NEGBINOMIAL \\n      Normal  NORMAL|GAUSS \\n      Normal mixture  NORMALMIX \\n      Pareto  PARETO \\n      Poisson  POISSON \\n      T  T \\n      Tweedie  TWEEDIE \\n      Uniform  UNIFORM \\n      Wald (inverse Gaussian)  WALD|IGAUSS \\n      Weibull  WEIBULL \\n\\nprobability \\n  is a numeric constant, variable, or expression that specifies the value of a random variable. \\nparm-1,…,parm-k \\n  are optional shape, location, or scale parameters that are appropriate for the specific distribution."},"SYSEXIST":{"help":"Returns a value that indicates whether an operating-environment variable exists \\nin your environment.\\n\\nSyntax:\\nSYSEXIST (argument) \\n\\nRequired Argument:\\nargument \\n  specifies a character variable that is the name of an operating-environment variable that \\n  you want to test."},"TIMEVALUE":{"help":"Returns the equivalent of a reference amount at a base date by using variable \\ninterest rates.\\n \\nSyntax: \\nTIMEVALUE(base-date, reference-date, reference-amount, compounding-interval,\\n  date-1, rate-1 <,date-2, rate-2,...>) \\n\\nRequired Arguments:\\nbase-date \\n  is a SAS date. The value that is returned is the time value of reference-amount at base-date. \\nreference-date \\n  is a SAS date. reference-date is the date of reference-amount. \\nreference-amount \\n  is numeric. reference-amount is the amount at reference-date. \\ncompounding-interval \\n  is a SAS interval. compounding-interval is the compounding interval. \\ndate \\n  is a SAS date. Each date is paired with a rate. date is the time that rate takes effect. \\nrate \\n  is a numeric percentage. Each rate is paired with a date. rate is the interest \\n  rate that starts on date."},"INVCDF":{"help":"[Valid for PROC FCMP only!]\\n\\nComputes the quantile from any distribution for which you have defined a cumulative \\ndistribution function (CDF).\\n\\nSyntax:\\nquantile=INVCDF(\'CDF-function-name\', options-array, cumulative-probability, \\nparameter-1, parameter-2, ..., parameter-n); \\n\\nRequired Arguments:\\nquantile \\n  specifies the quantile that is returned from the INVCDF function. \\n\'CDF-function-name\' \\n  specifies the name of the CDF function. Enclose CDF-function-name in quotation marks. \\n\\n  Requirement:CDF-function-name must be a function defined using the FCMP procedure. It must \\n  have a signature as follows: \\n    function <CDF-function-name> (x, parameter-1, parameter-2, …, parameter-n);\\n    endsub;\\n  \\noptions-array \\n  specifies an array of options to use with the INVCDF function. Options-array is used to \\n  control and monitor the process of inverting the CDF. Options-array can be a missing value (.), \\n  or it can have up to four of the following elements in the following order: \\n    initial-value \\n      specifies the initial guess for the quantile at which the inversion process starts. This is \\n      useful when you have an idea of the approximate value for quantile. The default for initial-value is 0.1. \\n    desired-accuracy \\n      specifies the desired relative accuracy of the quantile. You can specify any value in the range (0,0.1).\\n      The default for desired-accuracy is 1.0e-8.\\n    domain-type \\n      specifies the domain for the CDF function. A missing value or a value of 0 indicates a nonnegative \\n      support, that is [0,∞). Any other value indicates a support over the entire real line, that is (-∞,∞). \\n      The default for domain-type is 0. \\n    return-code \\n      specifies the return status. If options-array is of dimension 4 or more, then the fourth element contains \\n      the return status. Return-code can have one of the following values: \\n        <=0 \\n          indicates success. If negative, then the absolute value is the number of times the CDF function was \\n          evaluated in order to compute the quantile. A larger absolute value indicates longer convergence time. \\n        1 \\n          indicates that the quantile could not be computed. \\ncumulative-probability \\n  specifies the cumulative probability value for which the quantile is desired. This must be in the range [0,1). \\nparameters \\n  specifies the parameters of the distribution at which the quantile is desired. You must specify exactly the \\n  same number of parameters as required by the specified CDF function, and they should appear exactly in the \\n  same order as required by the specified CDF function."},"ISNULL":{"help":"[Valid for PROC FCMP only!]\\n\\nDetermines whether a pointer element of a structure is null.\\n\\nSyntax:\\nnumeric-variable = ISNULL(pointer-element); \\n\\nRequired Arguments:\\nnumeric-variable \\n  specifies a numeric value. \\npointer-element \\n  specifies a variable that contains the address of another variable."},"LIMMOMENT":{"help":"[Valid for PROC FCMP only!]\\n\\nComputes the limited moment of any distribution for which you have defined a cumulative distribution function (CDF). \\n\\nSyntax:\\nimom=LIMMOMENT(\'CDF-function-name\', options-array, order, limit, \\n\\nparameter-1, parameter-2, parameter-n); \\nRequired Arguments \\nimom \\n  specifies the limited moment that is returned from the LIMMOMENT function.\\n\'CDF-function-name\' \\n  specifies the name of the CDF function. Enclose CDF-function-name in quotation marks. \\n\\n  Requirement:CDF-function-name must be a function defined using the FCMP procedure. It must \\n  have a signature as follows: \\n    function <CDF-function-name> (x, parameter-1, parameter-2, …, parameter-n);\\n    endsub;\\n  \\noptions-array \\n  specifies an array of options to use with the LIMMOMENT function. Options-array is used to \\n  control and monitor the process of inverting the CDF. Options-array can be a missing value (.), \\n  or it can have up to four of the following elements in the following order: \\n    initial-value \\n      specifies the initial guess for the quantile at which the inversion process starts. This is \\n      useful when you have an idea of the approximate value for quantile. The default for initial-value is 0.1. \\n    desired-accuracy \\n      specifies the desired relative accuracy of the quantile. You can specify any value in the range (0,0.1).\\n      The default for desired-accuracy is 1.0e-8.\\n    domain-type \\n      specifies the domain for the CDF function. A missing value or a value of 0 indicates a nonnegative \\n      support, that is [0,∞). Any other value indicates a support over the entire real line, that is (-∞,∞). \\n      The default for domain-type is 0. \\n    return-code \\n      specifies the return status. If options-array is of dimension 4 or more, then the fourth element contains \\n      the return status. Return-code can have one of the following values: \\n        <=0 \\n          indicates success. If negative, then the absolute value is the number of times the CDF function was \\n          evaluated in order to compute the quantile. A larger absolute value indicates longer convergence time. \\n        1 \\n          indicates that the quantile could not be computed. \\norder \\n  specifies the order of the desired limited moment. This value must be in the range [1,10]. \\nlimit \\n  specifies the upper limit that is used to compute the desired limited moment. This value must be greater than 0. \\nparameters \\n  specifies the parameters of the distribution at which the limited moment is desired. You must specify exactly \\n  the same number of parameters as required by the specified CDF function, and they should appear exactly in \\n  the same order as required by the specified CDF function."},"READ_ARRAY":{"help":"[Valid for PROC FCMP only!]\\n    \\nReads data from a SAS data set into a PROC FCMP array variable.\\n\\nSyntax:\\nrc = READ_ARRAY(data_set_name, array_variable <, \'col_name_1\', ..., \'col_name_n\'>); \\n\\nRequired Arguments:\\nrc \\n  is 0 if the function is able to successfully read the data set. \\ndata_set_name \\n  specifies the name of the data set from which the array data will be read. data_set_name must be \\n  a character literal or variable that contains the member name (libname.memname) of the data set to \\n  be read from. \\narray_variable \\n  specifies the PROC FCMP array variable into which the data is read. array_variable must be a local \\n  temporary array variable because the function might need to grow or shrink its size to accommodate \\n  the size of the data set. \\n\\nOptional Argument:\\ncol_name \\n  specifies optional names for the specific columns of the data set that will be read. \\n  If specified, col_name must be a literal string enclosed in quotation marks. col_name cannot be a \\n  PROC FCMP variable. If column names are not specified, PROC FCMP reads all of the columns in the data set."},"RUN_MACRO":{"help":"[Valid for PROC FCMP only!]\\n\\nExecutes a predefined SAS macro.\\n\\nSyntax:\\nrc = RUN_MACRO(\'macro_name\' <, variable_1, ..., variable_n>); \\n\\nRequired Arguments:\\nrc \\n  is 0 if the function is able to submit the macro. The return code indicates only that the \\n  macro call was attempted. The macro itself should set the value of a SAS macro variable that \\n  corresponds to a PROC FCMP variable to determine whether the macro executed as expected. \\nmacro_name \\n  specifies the name of the macro to be run. \\n  Requirement:macro_name must be a string enclosed in quotation marks or a character variable \\n  that contains the macro to be executed. \\n\\nOptional Argument:\\nvariable \\n  specifies optional PROC FCMP variables, which are set by macro variables of the same name. \\n  These arguments must be PROC FCMP double or character variables. \\n  \\n  Before SAS executes the macro, SAS macro variables are defined with the same name and value \\n  as the PROC FCMP variables. After SAS executes the macro, the macro variable values are copied \\n  back to the corresponding PROC FCMP variables."},"RUN_SASFILE":{"help":"[Valid for PROC FCMP only!]\\n    \\nSyntax \\nrc = RUN_SASFILE(\'fileref_name\' <, variable-1, ..., variable-n>); \\n\\nRequired Arguments:\\nrc \\n  is 0 if the function is able to submit a request to execute the code that processes the SAS file. \\n  The return code indicates only that the call was attempted. \\nfileref_name \\n  specifies the name of the SAS fileref that points to the SAS code. \\n  Requirement:fileref_name must be a string enclosed in quotation marks or a character variable \\n  that contains the name of the SAS fileref. \\n\\nOptional Argument:\\nvariable \\n  specifies optional PROC FCMP variables that will be set by macro variables of the same name. \\n  These arguments must be PROC FCMP double or character variables. \\n  \\n  Before SAS executes the code that references the SAS file, the SAS macro variables are defined \\n  with the same name and value as the PROC FCMP variables. After execution, these macro variable \\n  values are copied back to the corresponding PROC FCMP variables."},"SOLVE":{"help":"[Valid for PROC FCMP only!]\\n    \\nComputes implicit values of a function.\\n\\nSyntax:\\nanswer = SOLVE(\'function-name\', options-array, expected-value, argument-1, ..., argument-n); \\n\\nRequired Arguments:\\nanswer \\n  specifies the value that is returned from the SOLVE function. \\n\'function-name\' \\n  specifies the name of the function. Enclose function-name in quotation marks. \\noptions-array \\n  specifies an array of options to use with the SOLVE function. Options-array is used to control and \\n  monitor the root-finding process. Options-array can be a missing value (.), or it can have up to five \\n  of the following elements in the following order:   \\n    initial-value \\n      specifies the starting value for the implied value. The default for the first call is 0.001. If \\n      the same line of code is executed again, then options-array uses the previously found implied value. \\n    absolute-criterion \\n      specifies a value for convergence. The absolute value of the difference between the expected value \\n      and the predicted value must be less than the value of absolute-criterion for convergence. \\n      Default:1.0e–12 \\n    relative-criterion \\n      specifies a value for convergence. When the change in the computed implied value is less than the \\n      value of relative-criterion, then convergence is assumed. \\n      Default:1.0e–6 \\n    maximum-iterations \\n      specifies the maximum number of iterations to use to find the solution. \\n      Default:100 \\n    solve-status \\n      can be one of the following values: \\n        0 successful. \\n        1 could not decrease the error. \\n        2 could not compute a change vector. \\n        3 maximum number of iterations exceeded. \\n        4 initial objective function is missing. \\nexpected-value \\n  specifies the expected value of the function of interest. \\nargument \\n  specifies the arguments to pass to the function that is being minimized."},"WRITE_ARRAY":{"help":"[Valid for PROC FCMP only!]\\n    \\nSyntax:\\nrc = WRITE_ARRAY(data_set_name, array_variable <, \'col_name_1\', ..., \'col_name_n\'>); \\n\\nRequired Arguments:\\nrc \\n  is 0 if the function is able to successfully write the data set. \\ndata_set_name \\n  specifies the name of the data set to which the array data will be written. data_set_name must \\n  be a character literal or variable that contains the member name (libname.memname) of the data \\n  set to be created. \\narray_variable \\n  specifies the PROC FCMP array or matrix variable whose contents will be written to data_set_name. \\n\\nOptional Argument:\\ncol_name \\n  specifies optional names for the columns of the data set that will be created. \\n  If specified, col_name must be a literal string enclosed in quotation marks. col_name cannot be \\n  a PROC FCMP variable. If column names are not specified, the column name will be the array name \\n  with a numeric suffix."},"GRDSVC_ENABLE":{"help":"[Valid in: %SYSFUNC or %QSYSFUNC Macro, DATA step]\\n    \\nEnables or disables one or all SAS sessions on a grid. \\n\\nSyntax:\\ngrdsvc_enable(identifier <, option-1; ... option-n> ) \\ngrdsvc_enable(identifier,\\"\\" | \\" ) \\n\\nRequired Argument:\\nidentifier \\n  specifies one or all server sessions to be enabled or disabled for grid execution. The identifier \\n  is specified as follows: \\n  \\n    server-ID \\n      specifies the name of a SAS/CONNECT server session to be enabled or disabled for grid execution. \\n    _ALL_ \\n      specifies that all SAS sessions are enabled or disabled for grid execution. \\n\\nOptional Arguments:\\nSASAPPSERVER=server-value | SERVER=server-value | RESOURCE=server-value\\n  specifies the name of a SAS Application Server that has been defined in the SAS Metadata Repository. \\n  The SAS Application Server contains the definition for the logical grid server that defines the grid environment. \\n\\nWORKLOAD=workload-value \\nidentifies the resource for the job to be executed on the grid. This value specifies an additional \\nresource requirement for which Platform Suite for SAS selects the appropriate grid nodes.\\n\\nJOBNAME=job-name-macro-variable \\nspecifies the macro variable that contains the name that is assigned to the job that is executed on the grid. \\n\\nJOBOPTS=job-opts-macro-variable \\n  specifies the macro variable that contains the job options. The job option name/value pairs are \\n  assigned to job-opts-macro-variable. \\n\\n\\"\\" | \\" \\ndisables grid execution for the specified server ID or all server sessions."},"GRDSVC_GETADDR":{"help":"[Valid in: %SYSFUNC or %QSYSFUNC Macro, DATA step] \\n    \\nReports the IP address of the grid node on which the SAS session was chosen to execute. \\n    \\nSyntax:\\ngrdsvc_getaddr(identifier)\\n\\nRequired Argument:\\nidentifier \\n  identifies the server session that is executing on the grid. The identifier can be specified \\n  as follows: \\n\\n    \\"\\"| \\" \\n      is an empty string that is used to refer to the computer on which the function is executing. \\n    \\n    server-ID \\n      specifies the server session that is executing on a grid."},"GRDSVC_GETINFO":{"help":"[Valid in: %SYSFUNC or %QSYSFUNC Macro, DATA step] \\n    \\nReports information about the grid environment.\\n\\nSyntax:\\ngrdsvc_getinfo(identifier)\\n\\nRequired Argument:\\nidentifier \\n  specifies the server session or the SAS Application Server whose details you want to have reported \\n  to the SAS log. The identifier is specified as follows: \\n  \\n    server-ID \\n      reports details about the specified server ID. The details that are returned by the GRDSRV_INFO \\n      function reflect the arguments that are specified in the GRDSVC_ENABLE function. \\n      Requirement:A server-ID cannot exceed eight characters. \\n    \\n    _ALL_ \\n      reports details about all server IDs to the SAS log. The details that are returned by the \\n      GRDSRV_INFO function reflect the arguments that are specified in the GRDSVC_ENABLE function. \\n    \\n    SASAPPSERVER=SAS-application-server | SERVER=SAS-application-server | SERVER=SAS-application-server\\n      reports information about the specified SAS Application Server to the SAS log. \\n    \\n    _SHOWID_ \\n      lists each server session and its status: enabled for grid execution, enabled for SMP execution, or disabled."},"GRDSVC_GETNAME":{"help":"[Valid in: %SYSFUNC or %QSYSFUNC Macro, DATA step] \\n    \\nReports the name of the grid node on which the SAS grid server session was chosen to execute. \\n\\nSyntax:\\ngrdsvc_getname(identifier)\\n\\nRequired Argument:\\nidentifier \\n  identifies the server session that is executing on the grid. The identifier can be specified as follows: \\n\\n    \\"\\" | \\" \\n      is an empty string that is used to refer to the computer at which the statement is executed. \\n\\n    server-ID \\n      specifies the server session that is executing on a grid. \\n      You use the same server-ID that you used to sign on to a server session using the RSUBMIT \\n      statement or the SIGNON statement.\\n      \\n      If the function is used in a DATA step, enclose server-ID in double or single quotation marks"},"GRDSVC_NNODES":{"help":"[Valid in: %SYSFUNC or %QSYSFUNC Macro, DATA step] \\n    \\nReports the total number of job slots that are available for use on a grid. \\n\\nSyntax:\\ngrdsvc_nnodes(argument;option) \\n\\nRequired Argument:\\n  SASAPPSERVER=SAS-application-server | SERVER=SAS-application-server | RESOURCE=SAS-application-server\\n    specifies the name of the SAS Application Server that has been defined in the SAS Metadata Repository. \\n\\nOptional Argument:\\n  WORKLOAD=workload-value \\n    identifies the resource for the type of job to be executed on the grid. This value specifies the \\n    workload requirements for which Platform Suite for SAS selects the grid nodes that contain these \\n    resources. \\n    \\n    The specified workload value should match one of the workload values that is defined in the \\n    SAS Application Server in the SAS Metadata Repository. \\n    \\n    Requirement:If you specify WORKLOAD=, you must also specify the SASAPPSERVER= option. Workload \\n    values are case sensitive."},"COT":{"help":"Returns the cotangent. \\n    \\nSyntax: COT(argument)\\nRequired Argument:\\nargument\\n  specifies a numeric constant, variable, or expression and is expressed in radians.\\n\\n  Restriction: argument cannot be 0 or a multiple of PI."},"CSC":{"help":"Returns the cosecant. \\n    \\nSyntax: CSC(argument) \\n\\nRequired Argument:\\nargument\\n  specifies a numeric constant, variable, or expression and is expressed in radians.\\n  \\n  Restriction: argument cannot be 0 or a multiple of PI."},"DOSUBL":{"help":"Imports macro variables from the calling environment, and exports macro variables back to the calling environment. \\n    \\nSyntax: DOSUBL(x)\\nRequired Argument: \\nx\\n  specifies a text string.\\n  \\nDetails:\\nThe DOSUBL function enables the immediate execution of SAS code after a text string is passed. \\nMacro variables that are created or updated during the execution of the submitted code are exported \\nback to the calling environment. \\n\\nDOSUBL returns a value of zero if SAS code was able to execute, and returns a nonzero value if SAS \\ncode was not able to execute."},"FCOPY":{"help":"Copies records from one fileref to another fileref, and returns a value that indicates whether the \\nrecords were successfully copied. \\n\\nSyntax: FCOPY(\'fileref-1\', \'fileref-2\')\\nRequired Arguments:\\n\'fileref-1\'\\n  specifies an existing fileref from which records are to be copied.\\n\'fileref-2\'\\n  specifies an existing fileref to which records are to be copied.\\n\\nDetails:\\nValues That Are Returned by the FCOPY Function\\n  FCOPY returns these values:\\n    •a value of 0 if records were copied without errors or warnings\\n    •a positive value if an error occurred\\n    •a negative value if a warning was issued\\n  You can use the SYSMSG function to retrieve error or warning messages, and you can use the SYSRC \\n  function to retrieve the return code.\\n\\nUsing Macro Variables with the FCOPY Function\\n  The following macro variables provide information for the FCOPY function:\\n    •The &SYSCC and &SYSERR macro variables are set if FCOPY writes an error or warning message to the log.\\n    •The &SYSCC and &SYSERR macro variables are not set if FCOPY returns a warning return code and there \\n      is no log output from FCOPY.\\n    •The &SYSERRORTEXT macro variable is set if FCOPY writes an error message to the log.\\n    •The &SYSWARNINGTEXT macro variable is set if FCOPY writes a warning message to the log."},"SEC":{"help":"Returns the secant. \\n \\nSyntax: SEC(argument)\\n\\nRequired Argument:\\nargument\\n  specifies a numeric constant, variable, or expression and is expressed in radians.\\n\\n  Restriction: argument cannot be an odd multiple of PI/2."},"TYPEOF":{"help":"Returns a value that indicates whether the argument is character or numeric.\\n\\nRestriction:\\nThe TYPEOF function is used exclusively with the Graph Template Language (GTL) and in WHERE clauses, \\nbut not in DATA steps.\\n\\nSyntax: TYPEOF(column) \\n\\nRequired Argument:\\ncolumn\\n  can have one of the following values:\\n  C\\n    indicates that the argument is a character value.\\n  N\\n    indicates that the argument is a numeric value."},"TZONEID":{"help":"Returns the current time zone ID.\\n\\nAlias: TZID \\n\\nSyntax: TZID=TZONEID() \\n\\nDetails:\\nThe TZONEID function returns a blank value is the TIMEZONE= option is blank or a user-defined time zone is specified."},"TZID":{"help":"Returns the current time zone ID.\\n\\nAlias: TZID \\n\\nSyntax: TZID=TZONEID() \\n\\nDetails:\\nThe TZONEID function returns a blank value is the TIMEZONE= option is blank or a user-defined time zone is specified."},"TZONENAME":{"help":"Returns the current standard or daylight savings time, time zone name.\\n\\nSyntax: TZONENAME() | TZONENAME<time-zone-id>\\n\\nOptional Argument: \\ntime-zone-id\\n  specifies a region/area value that is defined by SAS. When you specify a zone ID, the time zone that SAS uses \\n  is determined by time zone name and daylight savings time rules.\\n\\nDetails:\\nThe TZONENAME function returns a blank value if the TIMEZONE= option is blank."},"TZONEOFF":{"help":"Returns the user time zone offset.\\n\\nSyntax: TZONEOFF() | TZONEOFF(<time-zone-id, time-zone-name>)\\n\\nOptional Arguments:\\ntime-zone-id\\n  specifies a region/area value that is defined by SAS. When you specify a time zone ID, the time zone \\n  that SAS uses is determined by time zone name and daylight savings time rules."},"TZONES2U":{"help":"Converts a SAS date time value to a UTC date time value. \\n    \\nSyntax: TZONES2U <datetime, time-zone-name> \\n\\nOptional Arguments: \\ndatetime \\n  specifies a SAS datetime value. \\ntime-zone-name\\n  specifies a predefined time zone. Predefined time zone names take into consideration standard and daylight saving \\n  time, and rules for daylight savings time for that time zone."},"TZONEU2S":{"help":"Converts a UTC date time value to a SAS date time value. \\n    \\nSyntax: TZONEU2S <time-zone-ID> \\n\\nOptional Argument:\\ntime-zone-ID\\n  specifies a region/area value that is defined by SAS. When you specify a zone ID, the time zone that \\n  SAS uses is determined by time zone name and daylight savings time rules.Note:Time zone IDs are compatible \\n  with Java time zone names."},"SHA256":{"help":"Returns the result of the message digest of a specified string.\\n\\nSyntax: SHA256(string) \\n\\nRequired Argument:\\nstring\\n  specifies a character constant, variable, or expression.\\n\\nDetails:\\n\\nThe Basics\\n  The SHA256 function converts a string, based on the SHA256 algorithm, to a 256-bit hash value. \\n\\n  The SHA256 function does not format its own output. Use the $BINARYw. or $HEXw. formats to view readable results.\\n\\n  z/OS Specifics\\n  In the z/OS operating environment, because the SHA256 function might be operating on EBCDIC data, the message \\n  digest is different from the ASCII equivalent. For example, SHA256(\'ABC\') on an EBCDIC system means that SHA256 \\n  receives the bytes \'C1C2C3\'x and the digest is 5202BF40821662BF1AD7D9C9B558056775D9D6BF8AA1C00492BCA8556B02772F, \\n  whereas on an ASCII system, \'ABC\' is \'414243\'x and the digest is \\n  B5D4045C3F466FA91FE2CC6ABE79232A1A57CDF104F7A26E716E0A1E2789DF78."},"CLIBEXIST":{"help":"Syntax: CLIBEXIST(session name,caslib name)\\n    \\nReturns 0 when the specified caslib name is not found and 1 when the caslib is found. \\n\\nArguments:\\nsession name\\n  a valid session name\\ncaslib name\\n  a valid caslib name."},"GETCASURL":{"help":"The SAS function GETCASURL returns the URL value for connecting to the CAS Server Monitor \\nfor a CAS server. This function takes no parameters. \\n\\nRequirements: \\no The server name identified by the SAS CASHOST= option is used when constructing the URL. \\n  For example, \\"rdcgrd001.unx.sas.com\\". \\n  \\no The SAS SESSREF= option identifies a connection to the server identified by CASHOST=. \\n  This connection is used to obtain additional URL information. \\n\\nExample:\\n%put httpaddr= %sysfunc(getcasurl());\\nhttp://rdcgrd001.unx.sas.com:38281"},"GETLCASLIB":{"help":"Syntax: GETLCASLIB(libref)\\n    \\nReturns the caslib that was bound to a CAS LIBNAME engine libref in the CASLIB= option when it was assigned. \\n\\nNote:\\nIf a caslib is not bound, then the active caslib is returned.\\n    \\nArgument:\\nlibref\\n  specifies the caslib name that is associated with the library reference. "},"GETLSESSREF":{"help":"Syntax: GETLSESSREF (libref) \\n\\nReturns the session reference that is associated with a CAS LIBNAME engine libref. \\n\\nArgument:\\nlibref\\n  specifies the session reference name."},"GETLTAG":{"help":"Syntax: GETLTAG(libref) \\n\\nReturns the tag that was associated with a CAS LIBNAME engine libref in the TAG= option when it is assigned. \\n\\nNotes:\\nIf a tag was not associated, a zero-length string (\\"\\") is returned. \\nThe TAG= option is rarely used. It is useful after loading a server-side file into memory from \\na caslib that enables access to subdirectories with CASL. \\n\\nArgument:\\nlibref\\nspecifies the tag that is associated with the library reference. "},"SESSFOUND":{"help":"The SAS function SESSFOUND returns 0 when not found and 1 when the session is found. This function only \\nhas access to sessions connected using SAS Client interfaces. To return a full set of sessions known \\nto the CAS server use Proc CAS and the \\"listsessions\\" action or the CAS statement. \\n\\n  CAS mySess LISTSESSIONS ;\\n\\nThe SESSFOUND function has one parameter session name. The result is 0 for not found and 1 for found. \\n\\nExample:\\n\\n%put doIExist= %sysfunc(sessfound(mysess));\\ndoIExist= 0\\n \\n%put doIExist= %sysfunc(sessfound(existingSession));"},"GETSESSOPT":{"help":"The SAS function GETSESSOPT returns the value for a Cloud Analytic Services (CAS) session option.\\n    \\nEach CAS session has a set of server-side session options. \\n\\nThe GETSESSOPT function has two parameters: \\n a session name. \\n a session option name. You can use CAS mysess LISTSESSOPTS; to list the session option names or read \\n    them from the CASSESSOPTS= system option documentation.\\n\\nExample: List the active caslib\\n\\nSpecify code like the following to return the value of the CASLIB option. \\n\\n%put caslib = %sysfunc(GETSESSOPT(mysess, caslib)) ;\\n \\ndata work.one ; \\n  x = GETSESSOPT(\\"mysess\\", \\"caslib\\") ; \\n  put x= ;\\nrun;"},"ISDOUBLE":{"help":"Returns true if the type of value (parameter) is double; otherwise, it returns false.\\n \\n Boolean  isDouble (value);"},"ISINTEGER":{"help":"Returns true if the type of value (parameter) is integer; otherwise, it returns false.\\n \\n Boolean  isInteger (value);"},"ISDICTIONARY":{"help":"Returns true if the type of value (parameter) is dictionary; otherwise, it returns false.\\n \\n Boolean  isDictionary (value);"},"ISARRAY":{"help":"Returns true if the type of value (parameter) is array; otherwise, it returns false.\\n \\n Boolean  isArray (value);"},"ISTABLE":{"help":"Returns true if the type of value (parameter) is table; otherwise, it returns false.\\n \\n Boolean  isTable (value);"},"ISLIST":{"help":"Returns true if the type of value (parameter) is list; otherwise, it returns false.\\n \\n Boolean  isList (value);"},"ISSTRING":{"help":"Returns true if the type of value (parameter) is string; otherwise, it returns false.\\n \\n Boolean  isString (value);"},"ISBLOB":{"help":"Returns true if the type of value (parameter) is blob; otherwise, it returns false.\\n \\n Boolean  isBlob (value);"},"ISTYPE":{"help":"This is a generic version where the type is specified as the first argument.\\n    \\nisType( \\"<type>\\", value);"},"NEWTABLE":{"help":"Creates a new table. \\n    \\n  o 1st argument is a list of column names\\n  o 2nd argument is a list of types for each column\\n  o any further arguments are rows to be added to the table \\n  o A table with the given rows is returned. No rows are required.\\n\\nExample:\\n columns = {\\"make\\", \\"MSRP\\", \\"HP\\", \\"cylinders\\"};\\n coltypes = {\\"varchar\\", \\"int64\\", \\"integer\\",\\"int64\\"};\\n row1 = {\\"dodge\\", 20000, 250, 4};\\n row2 = {\\"ford\\", 30000, 200, 6};\\n table = newtable( \\"cars\\", columns, coltypes, row1, row2,...};\\n \\nThe name of the table can be specified as the first argument, but is not required. The default name is \\"nodeList\\"."},"ADD_TABLE_ATTR":{"help":"The ADD_TABLE_ATTR adds attributes to a table. The first parameter is the table. Then pairs of values are specified as the key and value. \\n\\n  rc =  add_table_attr( table, \\"Actionset\\",\\"tkimstat\\",  \\"Action\\",\\"Summary\\");\\n\\nYou may print the attributes of a table as \\n\\n   print table.attr;"},"DISCARD":{"help":"Discards the variables that are listed as arguments:\\n    \\nx[10] = 1;\\ny = 2;\\ndiscard(x,y);"},"TABCOLUMNS":{"help":"Gets the columns for a table:\\n    \\n  columns = tabcolumns( table);"},"TABTYPES":{"help":"Gets the types for a table.\\n    \\n coltypes  = tabtypes( table);\\n\\nThis and the TABCOLUMNS function are useful when creating a new table from an existing table."},"PRINTTABLE":{"help":"This prints a table to the specified location. This function allows better control over the output a table \\nas compared to \\"print table\\"; \\n\\n printtable(table, \\"<fileref>\\", columns)\\n\\nfileref can be:\\n o ods -- uses the default print location with ODS output when appropriate.\\n o log -- uses the default print location, but do not use ODS; uses the internal format routines.\\n o <name> -- uses the named fileref location for output.\\n o file:<path> -- uses the given path as the location for output. This file is closed after the table has been written.\\n\\n\\ncolumns specifies the number of columns to be printed per line."},"ADDROW":{"help":"Adds row to table.\\n    \\n  addrow(table,row1);"},"FINDTABLE":{"help":"This function will search the given value for the first table it sees. This is useful when a result \\nfrom an action has a table result, but you do not know the name, you just know it is there. \\n\\n  table = findtable( result);"},"TRACEBACK":{"help":"This will return a string consisting of the traceback from the current function.\\n    \\n  tb = traceback();"},"DICTIONARY":{"help":"Returns the value of a key from a dictionary. \\n    \\n  y = dictionary(dict, \\"name\\");\\n\\nIf the value does not exist, then a 0 is returned."},"EXISTS":{"help":"Determines if a key exists in a dictionary. \\n    \\n y = exists(dict,\\"name\\");\\n\\nThis returns TRUE or FALSE."},"READPATH":{"help":"This will read the contents of the file given into the variable as a string."},"SESSIONS":{"help":"Creates a session variable. \\n    \\nThis will get the session named casl:\\n \\n  ses = session(\\"casl\\");\\n\\nThis creates a session to \\"rdcgrd001\\" on port 17766 with user \\"username\\" and 23 nodes:\\n \\n  ses = session(\\"rdcgrd001\\", 17766, \\"username\\", 23);\\n\\nThe authentication is assumed to be Kerberos."},"SORT":{"help":"Returns a list sorted in ascending order.\\n\\nExample:\\n  list = { 9, 4, 5.2};\\n  slist = sort( list);\\n  print slist;\\n    {  4, 5.2 9 };"},"SORT_REV":{"help":"Returns a list sorted in descending order.\\n    \\nExample:\\n  slist = sort_rev( list);\\n  print slist;  \\n    {  9, 5.2, 4 }"},"GITFN_VERSION":{"help":"Syntax: version = GITFN_VERSION();\\n\\nValidate that libgit2 is available for use and if available report the version that is being used.\\n    \\nReturn Values: -1\\n  The libgit2 library is not available for use, no Git operations are available.\\n\\nversion\\n  The major and minor version of the library, such as 0.27."},"GITFN_CLONE":{"help":"Syntax: rc = GITFN_CLONE(uri,dir,<user>,<password>, <path to pub ssh key file>, <path to private ssh key file>);\\n\\nClone the specified repository into the target directory on SAS server.\\n\\nRequired Arguments\\nuri(in)\\n  Specifies the URI of the repository, such as https://github.com/mamonaco1973/itr.git.\\ndir(in)\\n  The path of a directory on the SAS server for the repository be cloned into.\\n  \\nOptional Arguments\\nuser(in)\\n  User name for a secured repository. Note: When using ssh, the user name must be the ssh user.\\npassword(in)\\n  Password for a secured repository. The password can be encoded with PROC PWENCODE.\\npath to the public ssh key file(in)\\n  The path to the public ssh key file.\\npath to the private ssh key file(in)\\n  The path to the private ssh key file.\\n\\nReturn Values\\n-1 The libgit2 library is not available for use, no Git operations are available.\\n0 The clone operation succeeded.\\n>0 Git support is available, but the clone operation failed. See the log for the return message \\n  from the Git server."},"GITFN_STATUS":{"help":"Syntax: n = GITFN_STATUS(dir);\\n\\nGet the number of status objects associated with the local repository. \\n\\nRequired Arguments\\ndir(in)\\n The path containing a cloned Git repository on the SAS server.\\nReturn Values\\n -1\\n   The libgit2 library is not available for use, no Git operations are available.\\n -2\\n   Git support is available but the status operation failed. See the log for the return message from the Git server.\\n n\\n   The number of status objects associated with the local repository. This value can be 0 or greater."},"GITFN_STATUS_GET":{"help":"Syntax: rc = GITFN_STATUS_GET(n,dir,attr,value);\\n    \\nGet the attribute of a status of object that was obtained from calling GITFN_STATUS on the local repository.\\n\\nRequired Arguments\\nn(in) The Nth status object to retrieve attributes from.\\ndir(in) The path containing a cloned GIT repository on the SAS server.\\nattr(in) The attribute to retrieve. Valid attributes are PATH, STATUS and STAGED.\\nvalue(out) Returns the value of the specified attribute.\\n\\nReturn Values\\n-1 The libgit2 library is not available for use, no Git operations are available.\\n-2 GIT support is available but no status objects were found for the specified repository.\\n0 Status object and attribute was found. The value was returned.\\n1 Status object was found, but the specified attribute is not valid.\\n2 Repository status found, but the Nth requested element does not exist."},"GITFN_STATUSFREE":{"help":"Syntax: n = GITFN_STATUSFREE(dir);\\n    \\nFree the status objects associated with a repository that were acquired with GITFN_STATUS.\\n\\nRequired Arguments\\ndir(in)\\nThe path containing a cloned GIT repository on the SAS server that has previously had GITFN_STATUS called.\\nReturn Values\\n-1\\nThe libgit2 library is not available for use, no GIT operations are available.\\n-2\\nInternal failure.\\n0\\nThe free operation was successful.\\n1\\nNo status information found for the specified repository."},"GITFN_IDX_ADD":{"help":"Syntax: GITFN_IDX_ADD(dir, file1, fileStatus1, file2, fileStatus2, ...);\\n    \\nStages 1 to N number of files in preparation for commit.\\n\\nRequired Arguments\\ndir(in)\\n  The path of the local Git Repository.\\nfile1(in)\\n  The relative path of the first file to be staged.\\nfileStatus1(in)\\n  The status of the file. New, Modified, Deleted, Renamed, or type change."},"GITFN_IDX_REMOVE":{"help":"Syntax: GITFN_IDX_REMOVE(dir, file1, file2, ...);\\n    \\nUn-stages 1 to N number of files.\\n\\nRequired Arguments\\ndir(in)\\n  The path of the local GIT Repository.\\nfile1(in)\\n  The relative path of the first file to be staged."},"GITFN_COMMIT":{"help":"Syntax: GITFN_COMMIT(dir, updateref, authorName, authorEmail, commitMessage);\\n    \\nCommits staged files to the local repository.\\n\\nRequired Arguments\\ndir(in)\\n  The path of the local GIT Repository.\\nupdateref(in)\\n  Reference to update. In most cases \\"HEAD\\" should be used.\\nauthorName(in)\\n  Commit author\'s name.\\nauthorEmail(in)\\n  Commit author\'s email.\\ncommitMessage(in)\\n  Commit message. Used for providing some details of the commit. Displayed in commit log."},"GITFN_PUSH":{"help":"Syntax: GITFN_PUSH(dir, username, password, pubSSHKeyPath, privSSHKeyPath);\\n    \\nPushes commits on the local repository to the remote repository.\\n\\nRequired Arguments\\ndir(in)\\n  The path of the local Git Repository.\\nRequired if authentication is required:\\nusername(in)\\n  User name used for authentication.\\npassword(in)\\n  Password used for authentication.\\npubSSHKeyPath(in)\\n  The path to the public SSH key file.\\nprivSSHKeyPath(in)\\n  The path to the private SSH key file."},"GITFN_PULL":{"help":"Syntax: GITFN_PULL(dir, username, password, pubSSHKeyPath, privSSHKeyPath);\\n\\nPulls changes from the remote repository that were pushed by other users.\\n\\nRequired Arguments\\ndir(in)\\n  The path of the local Git Repository.\\nRequired if authentication is required:\\nusername(in)\\n  User name used for authentication.\\npassword(in)\\n  Password used for authentication.\\npubSSHKeyPath(in)\\n  The path to the public SSH key file.\\nprivSSHKeyPath(in)\\n  The path to the private SSH key file."},"GITFN_COMMIT_LOG":{"help":"Syntax: n = GITFN_COMMIT_LOG(dir);\\n    \\nGet the number of commit objects associated with the local repository.   \\n    \\nRequired Arguments\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server.\\nReturn Values\\nn\\n  The number of commit objects associated with the local repository. \\n  This value can be 0 or greater."},"GITFN_COMMIT_GET":{"help":"Syntax: rc = GITFN_COMMIT_GET(n,dir,attr,value);\\n    \\nGet the attribute of a commit object that was obtained from calling GITFN_COMMIT_LOG on the local repository.    \\n    \\nRequired Arguments\\nn(in)\\n  The Nth commit object to retrieve attributes from.\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server.\\nattr(in)\\n  The attribute to retrieve. Valid attributes are id\\", \\"author\\", \\"email\\", \\"message\\", \\"parent_ids\\", and \\"time.\\"\\nvalue(out)\\n  Returns the value of the specified attribute."},"GITFN_COMMITFREE":{"help":"Syntax: n = GITFN_COMMITFREE(dir);\\n\\nFree the commit objects associated with a repository that were acquired with GITFN_COMMIT_LOG.    \\n    \\nRequired Arguments\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server that has previously had GITFN_COMMIT_LOG called.\\nReturn Values\\n-1  The libgit2 library is not available for use, no Git operations are available.\\n-2  Internal failure.\\n0  The free operation was successful.\\n1  No commit information found for the specified repository."},"GITFN_DIFF":{"help":"Syntax: n = GITFN_DIFF(dir, olderCommitID, newerCommitID);\\n    \\nGet the number of diffs between two commits.\\n  \\nRequired Arguments\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server.\\nolderCommitID(in)\\n  The older of the two commit IDs to run the diff between.\\nnewerCommitID(in)\\n  The newer of the two commit IDs to run the diff between.\\nReturn Values\\nn\\n  The number of diff objects associated with the local repository and \\n  the two commit ids. This value can be 0 or greater."},"GITFN_DIFF_GET":{"help":"Syntax: rc = GITFN_DIFF_GET(n,dir,attr,value);\\n    \\nRequired Arguments\\nn(in)\\n  The Nth commit object to retrieve attributes from.\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server.\\nattr(in)\\n  The attribute to retrieve. Valid attributes are File, Diff_Content, Diff_type.\\"\\nvalue(out)\\n  Returns the value of the specified attribute."},"GITFN_DIFF_FREE":{"help":"Syntax: n = GITFN_DIFF_FREE(dir, olderCommitID, newerCommitID);\\n\\nFree the diff objects associated with a repository and commit ids that were generated with GITFN_DIFF.\\n\\nRequired Arguments\\ndir(in)\\n  The path containing a cloned Git repository on the SAS server that has previously had GITFN_DIFF called.\\nolderCommitID(in)\\n  The commit ID of the older of the two commits.\\nnewerCommitID(in)\\n  The commit ID of the newer of the two commits.\\nReturn Values\\n-1 The libgit2 library is not available for use, no Git operations are available.\\n-2 Internal failure.\\n0 The free operation was successful.\\n1 No diff information found for the specified repository."},"GITFN_RESET":{"help":"Syntax: n = GITFN_RESET(dir, commitID, reset_type);\\n    \\nFunction to reset the local repository to a specific commit.\\n\\nRequired Arguments\\ndir(in) \\n  The path to the local GIT repository.\\ncommitID(in)\\n  The commit ID to reset to.\\nreset_type(in)\\n  Type of reset desired. HARD (reset working directory and index discard all local changes \\n  including uncommitted), MIXED (leave working directory untouched, reset index), or SOFT \\n  (leave working directory and index untouched)\\nReturn Values\\n0"},"GITFN_DEL_REPO":{"help":"Syntax: n = GITFN_DEL_REPO(dir);\\n    \\nFunction to delete a local Git repository and its contents.   \\n    \\nRequired Arguments\\ndir(in)\\n  The path to the local GIT repository.\\nReturn Values\\n0 on success.\\n-1 on failure."},"GITFN_NEW_BRANCH":{"help":"Syntax: branch = GITFN_NEW_BRANCH(dir, id, name, force);\\n\\nFunction to create a new Git branch.\\n    \\nRequired Arguments\\ndir(in)\\n  The path to the local Git repository.\\nid(in)\\n  The id of the Git commit level to branch.\\nname(in)\\n  The name to give the new branch.\\nforce(in)\\n  1 if the branch name specified is already in use, replace the branch location with this commit level\\nReturn Values\\n0 - on success.\\n-1 - when an error occurs."},"GITFN_CO_BRANCH":{"help":"Syntax: rc = GITFN_CO_BRANCH(dir, name);\\n\\nFunction to check out a Git branch.\\n    \\nRequired Arguments\\ndir(in)\\n  The path to the local Git repository.\\nname(in)\\n  The name of the Git branch to check out.\\nReturn Values\\n0 on success.\\n-1 when an error occurs."},"GITFN_MRG_BRANCH":{"help":"Syntax: rc = GITFN_MRG_BRANCH(path, branch, userid, email);\\n    \\nFunction to merge a Git branch.    \\n    \\nRequired Arguments\\npath(in)\\n  The path to the local Git repository.\\nbranch(in)\\n  The name of the Git branch to merge into the checked-out branch.\\nuserid(in)\\n  The user ID that is invoking the merge.\\nemail(in)\\n  The email address of the user that is invoking the merge.\\nReturn Values\\nrc = 0: success\\nrc = 1: branch already up-to-date\\nrc = -1: merge commit failed\\nrc = -2: index has conflicts, check log for conflicting files."},"GITFN_DIFF_IDX_F":{"help":"Syntax: rc = GITFN_DIFF_IDX_F(path, file path, DIFF_CONTENT);\\n\\nFunction to get the diff of a file that is in the index.\\n\\nRequired Arguments\\npath(in)\\n  The path to the local Git repository.\\nfile path(in)\\n  The file path relative to the local repository.\\nDIFF_CONTENT(out)\\n  Out variable that holds the content of the diff.\\nReturn Values\\nrc - 0 on success.\\nrc - 1 on failure."},"GITFN_RESET_FILE":{"help":"Syntax: rc = GITFN_RESET_FILE(path, file path); \\n    \\nRequired Arguments\\npath(in)\\n  The path to the local Git repository.\\nfile path(in)\\n  The file path relative to the local repository.\\nReturn Values\\nrc - 0 on success.\\nrc - 1 on failure."}}}')}}]);